def upload_framework_agreement(framework_slug):
    framework = data_api_client.get_framework(framework_slug)['frameworks']
    if framework['status'] not in ['standstill', 'live']:
        abort(404)
    supplier_framework = data_api_client.get_supplier_framework_info(current_user.supplier_id, framework_slug)['frameworkInterest']
    if not supplier_framework['onFramework']:
        abort(404)
    template_data = main.config['BASE_TEMPLATE_DATA']
    upload_error = None
    if not file_is_less_than_5mb(request.files['agreement']):
        upload_error = 'Document must be less than 5Mb'
    elif file_is_empty(request.files['agreement']):
        upload_error = 'Document must not be empty'
    if upload_error is not None:
        return (render_template('frameworks/agreement.html', framework=framework, supplier_framework=supplier_framework, upload_error=upload_error, **template_data), 400)
    agreements_bucket = s3.S3(current_app.config['DM_AGREEMENTS_BUCKET'])
    extension = get_extension(request.files['agreement'].filename)
    path = get_agreement_document_path(framework_slug, current_user.supplier_id, extension)
    agreements_bucket.save(path, request.files['agreement'], acl='private', download_filename='{}-{}-signed-framework-agreement{}'.format(sanitise_supplier_name(current_user.supplier_name), current_user.supplier_id, extension))
    data_api_client.register_framework_agreement_returned(current_user.supplier_id, framework_slug, current_user.email_address)
    try:
        email_body = render_template('emails/framework_agreement_uploaded.html', framework_name=framework['name'], supplier_name=current_user.supplier_name, supplier_id=current_user.supplier_id, user_name=current_user.name)
        send_email(current_app.config['DM_FRAMEWORK_AGREEMENTS_EMAIL'], email_body, current_app.config['DM_MANDRILL_API_KEY'], '{} framework agreement'.format(framework['name']), current_user.email_address, '{} Supplier'.format(framework['name']), ['{}-framework-agreement'.format(framework_slug)])
    except MandrillException as e:
        current_app.logger.error('Framework agreement email failed to send. error {error} supplier_id {supplier_id} email_hash {email_hash}', extra={'error': six.text_type(e), 'supplier_id': current_user.supplier_id, 'email_hash': hash_email(current_user.email_address)})
        abort(503, 'Framework agreement email failed to send')
    return redirect(url_for('.framework_agreement', framework_slug=framework_slug))

def level_check(self):
    if self.happiness > SETTLER.HAPPINESS_LEVEL_UP_REQUIREMENT:
        self.get_component(StorageComponent).inventory.alter(RES.CONSTRUCTION_MATERIAL, -self._upgrade_production.get_consumed_resources().get(RES.CONSTRUCTION_MATERIAL, 0))
        self.level_up()
        self._changed()
    elif self.happiness < SETTLER.HAPPINESS_LEVEL_DOWN_LIMIT:
        self.get_component(StorageComponent).inventory.alter(RES.CONSTRUCTION_MATERIAL, -self._upgrade_production.get_consumed_resources().get(RES.CONSTRUCTION_MATERIAL, 0))
        self.level_down()
        self._changed()

def prepare_form(form_request):
    form_data = {}
    form_data['user_agent'] = request.headers.get('User-Agent')
    form_data['src'] = request.args.get('src')
    form_data['extra_labels'] = request.args.getlist('label')
    form_data['url'] = request.args.get('url')
    if form_request.method == 'POST':
        json_data = form_request.get_json()
        form_data.update(json_data)
    channel = ''
    details = form_data.get('details')
    if details:
        channel = details.get('channel')
    if channel == 'release':
        return {'redirect': '/new-url'}
    return form_data

def testRepr(self) -> None:
    self.assertEqual(str(self.param1), self.param1_repr)
    self.assertEqual(str(self.param2), self.param2_repr)

def run(self):
    if not Screenshot().have_pil():
        log.warning('Python Image Library is not installed, screenshots are disabled')
        return False
    img_counter = 0
    img_last = None
    while self.do_run:
        time.sleep(SHOT_DELAY)
        try:
            img_current = Screenshot().take()
        except IOError as e:
            log.error('Cannot take screenshot: %s', e)
            continue
        if img_last and Screenshot().equal(img_last, img_current, SKIP_AREA):
            continue
        img_counter += 1
        with BytesIO() as tmpio:
            img_current.save(tmpio, format='JPEG')
            tmpio.seek(0)
            if self.screenshots_qr and HAVE_CV2:
                url = handle_qr_codes(tmpio)
                if url:
                    log.info('QR code detected with URL: %s', url)
                    try:
                        os.startfile(url)
                    except Exception as e:
                        log.error('Failed to open QR URL: %s', e)
                tmpio.seek(0)
            nf = NetlogFile(f"shots/{str(img_counter).rjust(4, '0')}.jpg")
            for chunk in tmpio:
                nf.sock.sendall(chunk)
            nf.close()
            img_last = img_current
    return True

def format_courserun_for_dashboard(course_run, status_for_user, certificate=None, position=1, mmtrack=None):
    if course_run is None:
        return
    formatted_run = {'id': course_run.id, 'course_id': course_run.edx_course_key, 'title': course_run.title, 'status': status_for_user, 'position': position, 'course_start_date': course_run.start_date, 'course_end_date': course_run.end_date, 'fuzzy_start_date': course_run.fuzzy_start_date}
    extra_fields = CourseFormatConditionalFields.get_assoc_field(status_for_user)
    for extra_field in extra_fields:
        formatted_run[extra_field['format_field']] = getattr(course_run, extra_field['course_run_field'])
    if status_for_user == CourseStatus.PASSED:
        if certificate is not None:
            formatted_run['grade'] = certificate.grade
            formatted_run['certificate_url'] = certificate.download_url
        else:
            log.error('A valid certificate was expected')
    if status_for_user == CourseStatus.CURRENTLY_ENROLLED:
        if mmtrack is not None:
            try:
                final_grade = api.get_final_grade(mmtrack.user, course_run)
                if final_grade is not None:
                    formatted_run['grade'] = final_grade.grade
            except Exception as e:
                log.error(f'Error retrieving current grade for user {mmtrack.user} and course run {course_run}: {e}')
    if status_for_user == CourseStatus.OFFERED or status_for_user == CourseStatus.CAN_UPGRADE:
        try:
            course_price = CoursePrice.objects.get(course_run=course_run, is_valid=True)
            formatted_run['price'] = course_price.price
        except CoursePrice.DoesNotExist:
            pass
    return formatted_run

