def compare_ode_sol(sol1, sol2, func, *args):
    from sympy.core.basic import C, S
    if sol1 == sol2:
        return 0
    if isinstance(sol1, list) or isinstance(sol1, tuple):
        sol1len = sum([len(str(i)) for i in sol1])
        sol1 = sorted(sol1, cmp=lambda x, y: compare_ode_sol(x, y, func, *args))[len(sol1) - 1]
    else:
        sol1len = len(str(sol1))
    if isinstance(sol2, list) or isinstance(sol2, tuple):
        sol2len = sum([len(str(i)) for i in sol2])
        sol2 = sorted(sol2, cmp=lambda x, y: compare_ode_sol(x, y, func, *args))[len(sol2) - 1]
    else:
        sol2len = len(str(sol2))
    intcmp = int(sol1.has(C.Integral)) - int(sol2.has(C.Integral))
    if intcmp:
        return intcmp
    sol1s = 0
    sol2s = 0
    if sol1.lhs == func and (not sol1.rhs.has(func)) or (sol1.rhs == func and (not sol1.lhs.has(func))):
        sol1s = 1
    if sol2.lhs == func and (not sol2.rhs.has(func)) or (sol2.rhs == func and (not sol2.lhs.has(func))):
        sol2s = 1
    if sol2s - sol1s:
        return sol2s - sol1s
    try:
        sol1sol = solve(sol1, func)
        if sol1sol == []:
            raise NotImplementedError
    except NotImplementedError:
        pass
    else:
        sol1s = 1
    try:
        sol2sol = solve(sol2, func)
        if sol2sol == []:
            raise NotImplementedError
    except NotImplementedError:
        pass
    else:
        sol2s = 1
    if sol2s - sol1s:
        return sol2s - sol1s
    return cmp(sol1len, sol2len)

def ProcessTimelineEvent(self, timeline_event, parent):
    start = timeline_event['s'] - self.start_time
    end = timeline_event['e'] - self.start_time
    if end > start:
        elapsed = end - start
        thread = timeline_event['t']
        name = self.event_name_lookup[timeline_event['n']]
        if 'main_thread' in self.cpu and thread == self.cpu['main_thread']:
            if elapsed > 50000:
                if start - self.interactive_start > 500000:
                    self.interactive.append([int(math.ceil(self.interactive_start / 1000.0)), int(math.floor(start / 1000.0))])
                self.interactive_start = end
                self.interactive_end = None
            else:
                self.interactive_end = end
        if 'js' in timeline_event:
            script = timeline_event['js']
            js_start = start / 1000.0
            js_end = end / 1000.0
            if self.scripts is None:
                self.scripts = {}
            if 'main_thread' not in self.scripts and 'main_thread' in self.cpu:
                self.scripts['main_thread'] = self.cpu['main_thread']
            if thread not in self.scripts:
                self.scripts[thread] = {}
            if script not in self.scripts[thread]:
                self.scripts[thread][script] = {}
            if name not in self.scripts[thread][script]:
                self.scripts[thread][script][name] = []
            new_duration = True
            periods = self.scripts[thread][script][name]
            for period in periods:
                if len(period) >= 2 and js_start >= period[0] and (js_end <= period[1]):
                    new_duration = False
                    break
            if new_duration:
                periods.append([js_start, js_end])
        slice_usecs = self.cpu['slice_usecs']
        first_slice = int(float(start) / float(slice_usecs))
        last_slice = int(float(end) / float(slice_usecs))
        for slice_number in xrange(first_slice, last_slice + 1):
            slice_start = slice_number * slice_usecs
            slice_end = slice_start + slice_usecs
            used_start = max(slice_start, start)
            used_end = min(slice_end, end)
            slice_elapsed = used_end - used_start
            self.AdjustTimelineSlice(thread, slice_number, name, parent, slice_elapsed)
        if 'c' in timeline_event:
            for child in timeline_event['c']:
                self.ProcessTimelineEvent(child, name)

async def export(self, job, oid, options):
    pool = await self._get_instance(oid)
    job.set_progress(5, 'Retrieving pool attachments')
    attachments = await self.__attachments(pool)
    if options['cascade']:
        job.set_progress(10, 'Deleting pool attachments')
        await self.__delete_attachments(attachments, pool)
    job.set_progress(20, 'Stopping VMs using this pool (if any)')
    await self.middleware.call('vm.stop_by_pool', pool['name'], True)
    job.set_progress(30, 'Stopping jails using this pool (if any)')
    for jail_host in attachments['jails']:
        await self.middleware.call('jail.stop', jail_host)
    job.set_progress(30, 'Removing pool disks from swap')
    disks = [i async for i in await self.middleware.call('pool.get_disks')]
    await self.middleware.call('disk.swaps_remove_disks', disks)
    sysds = await self.middleware.call('systemdataset.config')
    if sysds['pool'] == pool['name']:
        job.set_progress(40, 'Reconfiguring system dataset')
        sysds_job = await self.middleware.call('systemdataset.update', {'pool': None, 'pool_exclude': pool['name']})
        await sysds_job.wait()
        if sysds_job.error:
            raise CallError(sysds_job.error)
    if pool['status'] == 'OFFLINE':
        pass
    elif options['destroy']:
        job.set_progress(60, 'Destroying pool')
        try:
            if await self.middleware.call('notifier.contains_jail_root', pool['path']):
                await self.middleware.call('notifier.delete_plugins')
        except Exception:
            pass
        await self.middleware.call('zfs.pool.delete', pool['name'])
        job.set_progress(80, 'Cleaning disks')
        for disk in disks:
            await self.middleware.call('disk.unlabel', disk)
        await self.middleware.call('disk.geli_detach', pool, True)
        if pool['encrypt'] > 0:
            try:
                os.remove(pool['encryptkey_path'])
            except OSError as e:
                self.logger.warn('Failed to remove encryption key %s: %s', pool['encryptkey_path'], e, exc_info=True)
    else:
        job.set_progress(80, 'Exporting pool')
        await self.middleware.call('zfs.pool.export', pool['name'])
        await self.middleware.call('disk.geli_detach', pool)
    job.set_progress(90, 'Cleaning up')
    if os.path.isdir(pool['path']):
        try:
            os.rmdir(pool['path'])
        except OSError as e:
            self.logger.warn('Failed to remove pointoint %s: %s', pool['path'], e)
    await self.middleware.call('datastore.delete', 'storage.volume', oid)
    await self.middleware.call('service.restart', 'cron')
    await self.middleware.call_hook('pool.post_export', pool=pool, options=options)

