def import_jurisdiction(org_importer, jurisdiction):
    metadata = jurisdiction.get_metadata()
    metadata['_type'] = 'metadata'
    metadata['_id'] = jurisdiction.jurisdiction_id
    metadata['latest_update'] = datetime.datetime.utcnow()
    if 'name' not in metadata or not isinstance(metadata['name'], str):
        raise ValueError("Invalid metadata: 'name' is required and must be a string.")
    if 'parties' not in metadata or not isinstance(metadata['parties'], list):
        raise ValueError("Invalid metadata: 'parties' is required and must be a list.")
    db.metadata.save(metadata)
    org = {'_type': 'organization', 'classification': 'jurisdiction', 'parent_id': None, 'jurisdiction_id': jurisdiction.jurisdiction_id, 'name': metadata['name']}
    if 'other_names' in metadata:
        org['other_names'] = metadata['other_names']
    if 'parent_id' in metadata:
        org['parent_id'] = metadata['parent_id']
    org_importer.import_object(org)
    for party in metadata['parties']:
        org = {'_type': 'organization', 'classification': 'party', 'name': party['name'], 'parent_id': None}
        org_importer.import_object(org)

def _render_to_grayscale(self) -> np.ndarray:
    self.viewer.observer_vehicle = self.observer_vehicle
    self.viewer.display()
    raw_rgb = self.viewer.get_image()
    raw_rgb = np.moveaxis(raw_rgb, 0, 1)
    return np.dot(raw_rgb[..., :3], self.weights).clip(0, 255).astype(np.uint8)

def add_provisioning_network(self, task):
    LOG.debug('Binding flat network ports')
    node = task.node
    host_id = node.instance_info.get('nova_host_id')
    if not host_id:
        return
    ports = [p for p in task.ports if not p.portgroup_id]
    portgroups = task.portgroups
    client = neutron.get_client(task.context.auth_token)
    for port_like_obj in ports + portgroups:
        vif_port_id = port_like_obj.extra.get('vif_port_id') or port_like_obj.internal_info.get('tenant_vif_port_id')
        if not vif_port_id:
            continue
        body = {'port': {'binding:host_id': host_id}}
        try:
            client.update_port(vif_port_id, body)
        except neutron_exceptions.NeutronClientException as e:
            msg = _('Unable to set binding:host_id for neutron port %(port_id)s. Error: %(err)s') % {'port_id': vif_port_id, 'err': e}
            LOG.exception(msg)
            raise exception.NetworkError(msg)

def _gap_init_(self):
    if not self.is_finite():
        return 'AbelianPcpGroup(%s)' % list(self.invariants())
    return 'AbelianGroup(%s)' % list(self.gens_orders())

def _hadoop_streaming_commands(self, step_num):
    version = self.get_hadoop_version()
    (mapper, bash_wrap_mapper) = self._render_substep(step_num, 'mapper')
    (combiner, bash_wrap_combiner) = self._render_substep(step_num, 'combiner')
    (reducer, bash_wrap_reducer) = self._render_substep(step_num, 'reducer')
    if combiner is not None and (not supports_combiners_in_hadoop_streaming(version)):
        if version < (0, 20):
            bash_wrap_mapper = True
            mapper = '%s | sort | %s' % (mapper, combiner)
            combiner = None
            bash_wrap_combiner = False
    if bash_wrap_mapper:
        mapper = bash_wrap(mapper)
    if bash_wrap_combiner:
        combiner = bash_wrap(combiner)
    if bash_wrap_reducer:
        reducer = bash_wrap(reducer)
    return (mapper, combiner, reducer)

import locale
import ConfigParser

def __get_ocrlang(self):
    try:
        ocrlang = self._configparser.get('OCR', 'Lang')
        if ocrlang == 'None':
            return None
        return ocrlang
    except ConfigParser.NoOptionError:
        (lang, _) = locale.getdefaultlocale()
        if lang is None:
            return 'eng'
        return lang.split('_')[0]

def aspirate(self, pipette_id: str, labware_id: str, well_name: str, well_location: WellLocation, volume: float, pipette_context: Any) -> commands.AspirateResult:
    request = commands.AspirateCreate(params=commands.AspirateParams(pipetteId=pipette_id, labwareId=labware_id, wellName=well_name, wellLocation=well_location, volume=volume, flowRate=pipette_context.flow_rate))
    result = self._transport.execute_command(request=request)
    return cast(commands.AspirateResult, result)

def sample_boundaries(blocks: List[ObjectRef[Block]], sort_key: SortKey, num_reducers: int) -> List[T]:
    columns = sort_key.get_columns()
    n_samples = int(num_reducers * 10 / len(blocks))
    sample_block = cached_remote_fn(_sample_block)
    sample_results = [sample_block.remote(block, n_samples, sort_key) for block in blocks]
    sample_bar = ProgressBar(SortTaskSpec.SORT_SAMPLE_SUB_PROGRESS_BAR_NAME, len(sample_results))
    samples = sample_bar.fetch_until_complete(sample_results)
    sample_bar.close()
    del sample_results
    samples = [s for s in samples if len(s) > 0]
    if len(samples) == 0:
        return [None] * (num_reducers - 1)
    builder = DelegatingBlockBuilder()
    for sample in samples:
        builder.add_block(sample)
    samples = builder.build()
    samples_dict = BlockAccessor.for_block(samples).to_numpy(columns=columns)
    samples_list = list(zip(*samples_dict.values()))

    def is_na(x):
        if x is None:
            return True
        x = np.asarray(x)
        if np.issubdtype(x.dtype, np.number):
            return np.isnan(x)
        return False
    for (i, desc) in list(enumerate(sort_key.get_descending()))[::-1]:
        samples_list.sort(key=lambda sample: NULL_SENTINEL if is_na(sample[i]) else sample[i], reverse=desc)
    quantile_indices = [int(q * (len(samples_list) - 1)) for q in np.linspace(0, 1, num_reducers + 1)]
    return [samples_list[i] for i in quantile_indices[1:-1]]

def _sample_block(block: Block, n_samples: int, sort_key: SortKey) -> Block:
    return BlockAccessor.for_block(block).sample(n_samples, sort_key)

def fit_from_bb(self, image, bounding_box, gt_shape=None, **kwargs):
    algo_result = self.algorithm.run(image, bounding_box, gt_shape=gt_shape)
    return Result(image, self, [algo_result], gt_shape=gt_shape)

from contextlib import contextmanager
import responses

@contextmanager
def _activate_mock(url, mock_response, method='get'):
    if mock_response and _environment_supports_mocks():
        with responses.RequestsMock() as rsps:
            http_method = getattr(responses, method.upper())
            rsps.add_callback(http_method, url, callback=mock_response)
            yield
    else:
        yield

async def htlc_switch(self):
    await self.initialized
    while True:
        await asyncio.sleep(0.1)
        self.ping_if_required()
        for (chan_id, chan) in self.channels.items():
            if not chan.can_send_ctx_updates():
                continue
            self.maybe_send_commitment(chan)
            done = set()
            unfulfilled = chan.hm.log.get('unfulfilled_htlcs', {})
            for (htlc_id, (local_ctn, remote_ctn, onion_packet_hex, forwarded)) in unfulfilled.items():
                if chan.get_oldest_unrevoked_ctn(LOCAL) <= local_ctn:
                    continue
                if chan.get_oldest_unrevoked_ctn(REMOTE) <= remote_ctn:
                    continue
                chan.logger.info(f'found unfulfilled htlc: {htlc_id}')
                htlc = chan.hm.log[REMOTE]['adds'][htlc_id]
                payment_hash = htlc.payment_hash
                error_reason = None
                error_bytes = None
                preimage = None
                onion_packet_bytes = bytes.fromhex(onion_packet_hex)
                onion_packet = None
                try:
                    if self.network.config.get('test_fail_malformed_htlc'):
                        raise InvalidOnionPubkey()
                    onion_packet = OnionPacket.from_bytes(onion_packet_bytes)
                    processed_onion = process_onion_packet(onion_packet, associated_data=payment_hash, our_onion_private_key=self.privkey)
                except UnsupportedOnionPacketVersion:
                    error_reason = OnionRoutingFailureMessage(code=OnionFailureCode.INVALID_ONION_VERSION, data=sha256(onion_packet_bytes))
                except InvalidOnionPubkey:
                    error_reason = OnionRoutingFailureMessage(code=OnionFailureCode.INVALID_ONION_KEY, data=sha256(onion_packet_bytes))
                except InvalidOnionMac:
                    error_reason = OnionRoutingFailureMessage(code=OnionFailureCode.INVALID_ONION_HMAC, data=sha256(onion_packet_bytes))
                except Exception as e:
                    self.logger.info(f'error processing onion packet: {e!r}')
                    error_reason = OnionRoutingFailureMessage(code=OnionFailureCode.TEMPORARY_NODE_FAILURE, data=b'')
                else:
                    if processed_onion.are_we_final:
                        (preimage, error_reason) = self.maybe_fulfill_htlc(chan=chan, htlc=htlc, onion_packet=onion_packet, processed_onion=processed_onion)
                    elif not forwarded:
                        error_reason = self.maybe_forward_htlc(chan=chan, htlc=htlc, onion_packet=onion_packet, processed_onion=processed_onion)
                        if not error_reason:
                            unfulfilled[htlc_id] = (local_ctn, remote_ctn, onion_packet_hex, True)
                    else:
                        if payment_hash not in self.lnworker.pending_payments:
                            self.lnworker.pending_payments[payment_hash] = asyncio.Future()
                        f = self.lnworker.pending_payments[payment_hash]
                        if f.done():
                            payment_attempt = f.result()
                            preimage = payment_attempt.preimage
                            error_bytes = payment_attempt.error_bytes
                            error_reason = payment_attempt.error_reason
                    if preimage:
                        await self.lnworker.enable_htlc_settle.wait()
                        self.fulfill_htlc(chan, htlc.htlc_id, preimage)
                        done.add(htlc_id)
                if error_reason or error_bytes:
                    self.fail_htlc(chan=chan, htlc_id=htlc.htlc_id, onion_packet=onion_packet, reason=error_reason, error_bytes=error_bytes)
                    done.add(htlc_id)
            for htlc_id in done:
                unfulfilled.pop(htlc_id)

def handle_GET(self, request, context):
    try:
        referer_host = request.META.get('HTTP_REFERER', '').split('/')[2]
        internal_referer = referer_host == request.META.get('HTTP_HOST')
    except IndexError:
        internal_referer = False
    if 'generic_web_browser' in device_parents[request.device.devid] and (not request.session.get('home:desktop_shown', False)) and (not request.GET.get('preview') == 'true') and (not internal_referer) and (not settings.DEBUG) and conf.has_app('molly.apps.desktop') and (request.REQUEST.get('format') is None):
        return self.redirect(reverse('desktop:index'), request)
    messages = []
    if not request.session.get('home:opera_mini_warning', False) and request.browser.mobile_browser == u'Opera Mini':
        messages.append(_("Please note that the 'Mobile View' on Opera Mini does not display this site correctly. To ensure correct operation of this site, ensure 'Mobile View' is set to Off in Opera settings"))
        request.session['home:opera_mini_warning'] = True
    if UserMessage.objects.filter(read=False, session_key=request.session.session_key).count():
        messages.append({'url': reverse('home:messages'), 'body': _('You have a message from the developers')})
    if has_app_by_application_name('molly.apps.weather'):
        weather_id = app_by_application_name('molly.apps.weather').location_id
        weather = Weather.objects.get(ptype='o', location_id=weather_id)
    else:
        weather = None
    applications = [{'application_name': app.application_name, 'local_name': app.local_name, 'title': app.title, 'url': reverse('%s:index' % app.local_name) if app.has_urlconf else None, 'display_to_user': app.display_to_user} for app in conf.all_apps()]
    for (i, app) in enumerate([app for app in applications if app['display_to_user']][:9]):
        app['accesskey'] = i + 1
    context = {'applications': applications, 'hide_feedback_link': True, 'is_christmas': datetime.now().month == 12, 'messages': messages, 'favourites': get_favourites(request), 'weather': weather}
    return self.render(request, context, 'home/index', expires=timedelta(minutes=10))

