def update_snapshot(self, data: bytes):
    if self.timestamp is None:
        raise RuntimeError('Cannot update snapshot before timestamp')
    if self.targets is not None:
        raise RuntimeError('Cannot update snapshot after targets')
    logger.debug('Updating snapshot')
    meta = self.timestamp.signed.meta['snapshot.json']
    hashes = meta.hashes or {}
    for (algo, stored_hash) in hashes.items():
        digest_object = sslib_hash.digest(algo)
        digest_object.update(data)
        observed_hash = digest_object.hexdigest()
        if observed_hash != stored_hash:
            raise exceptions.BadHashError(stored_hash, observed_hash)
    try:
        new_snapshot = Metadata.from_bytes(data)
    except DeserializationError as e:
        raise exceptions.RepositoryError('Failed to load snapshot') from e
    if new_snapshot.signed.type != 'snapshot':
        raise exceptions.RepositoryError(f"Expected 'snapshot', got '{new_snapshot.signed.type}'")
    if not verify_with_threshold(self.root, 'snapshot', new_snapshot):
        raise exceptions.UnsignedMetadataError('New snapshot is not signed by root', new_snapshot.signed)
    if new_snapshot.signed.version != self.timestamp.signed.meta['snapshot.json'].version:
        raise exceptions.BadVersionNumberError(f"Expected snapshot version {self.timestamp.signed.meta['snapshot.json'].version}, got {new_snapshot.signed.version}")
    if self.snapshot is not None:
        for (filename, fileinfo) in self.snapshot.signed.meta.items():
            new_fileinfo = new_snapshot.signed.meta.get(filename)
            if new_fileinfo is None:
                raise exceptions.RepositoryError(f"New snapshot is missing info for '{filename}'")
            if new_fileinfo.version < fileinfo.version:
                raise exceptions.BadVersionNumberError(f'Expected {filename} version {new_fileinfo.version}, got {fileinfo.version}.')
    if new_snapshot.signed.is_expired(self.reference_time):
        raise exceptions.ExpiredMetadataError('New snapshot is expired')
    self._trusted_set['snapshot'] = new_snapshot
    logger.debug('Updated snapshot')

def update_snapshot(self, data: bytes):
    if self.timestamp is None:
        raise RuntimeError('Cannot update snapshot before timestamp')
    if self.targets is not None:
        raise RuntimeError('Cannot update snapshot after targets')
    logger.debug('Updating snapshot')
    meta = self.timestamp.signed.meta['snapshot.json']
    hashes = meta.hashes or {}
    for (algo, stored_hash) in hashes.items():
        digest_object = sslib_hash.digest(algo)
        digest_object.update(data)
        observed_hash = digest_object.hexdigest()
        if observed_hash != stored_hash:
            raise exceptions.BadHashError(stored_hash, observed_hash)
    try:
        new_snapshot = Metadata.from_bytes(data)
    except DeserializationError as e:
        raise exceptions.RepositoryError('Failed to load snapshot') from e
    if new_snapshot.signed.type != 'snapshot':
        raise exceptions.RepositoryError(f"Expected 'snapshot', got '{new_snapshot.signed.type}'")
    if not verify_with_threshold(self.root, 'snapshot', new_snapshot):
        raise exceptions.UnsignedMetadataError('New snapshot is not signed by root', new_snapshot.signed)
    if new_snapshot.signed.version != self.timestamp.signed.meta['snapshot.json'].version:
        raise exceptions.BadVersionNumberError(f"Expected snapshot version {self.timestamp.signed.meta['snapshot.json'].version}, got {new_snapshot.signed.version}")
    if self.snapshot is not None:
        for (filename, fileinfo) in self.snapshot.signed.meta.items():
            new_fileinfo = new_snapshot.signed.meta.get(filename)
            if new_fileinfo is None:
                raise exceptions.RepositoryError(f"New snapshot is missing info for '{filename}'")
            if new_fileinfo.version < fileinfo.version:
                raise exceptions.BadVersionNumberError(f'Expected {filename} version {new_fileinfo.version}, got {fileinfo.version}.')
    if new_snapshot.signed.is_expired(self.reference_time):
        raise exceptions.ExpiredMetadataError('New snapshot is expired')
    self._trusted_set['snapshot'] = new_snapshot
    logger.debug('Updated snapshot')

def get_execution_sequence(self):
    condensed_graph = self.__create_condensed_graph()
    execution_sequence = []
    while True:
        leaves = self.__get_leaves(condensed_graph)
        if not leaves:
            break
        parallel_tasks = [tuple(condensed_graph.nodes[node_id]['members']) for node_id in leaves]
        execution_sequence.append(parallel_tasks)
        condensed_graph.remove_nodes_from(leaves)
    return list(reversed(execution_sequence))

def on_prepare(self):
    if not self.settings['data']:
        self.settings['data'] = 'io.github.Pithos-tray-symbolic'
    self.preferences_dialog = NotificationIconPluginPrefsDialog(self.window, self.settings)

    def on_settings_changed(settings, key):
        if key == 'data' and self.statusnotifieritem:
            self.statusnotifieritem.set_icon_name(settings[key])
    self.settings.connect('changed', on_settings_changed)

    def on_proxy_ready(obj, result, user_data=None):
        try:
            self.proxy = obj.new_finish(result)
        except GLib.Error as e:
            self.prepare_complete(error='Failed to connect to StatusNotifierWatcher {}'.format(e))
        else:
            logging.info('Connected to StatusNotifierWatcher')
            self.statusnotifieritem = PithosStatusNotifierItem(self.window, connection=self.proxy.get_connection())
            self.prepare_complete()
    Gio.DBusProxy.new(self.bus, Gio.DBusProxyFlags.DO_NOT_LOAD_PROPERTIES | Gio.DBusProxyFlags.DO_NOT_CONNECT_SIGNALS, None, 'org.kde.StatusNotifierWatcher', '/StatusNotifierWatcher', 'org.kde.StatusNotifierWatcher', None, on_proxy_ready, None)

    def on_watcher_appeared(conn, name, name_owner, user_data=None):
        logging.info('StatusNotifierWatcher appeared')

    def on_watcher_disappear(conn, name, user_data=None):
        logging.info('StatusNotifierWatcher disappeared')
    Gio.bus_watch_name_on_connection(self.bus, 'org.kde.StatusNotifierWatcher', Gio.BusNameWatcherFlags.AUTO_START, on_watcher_appeared, on_watcher_disappear)

def test(access_key_id, account, cleanup, config, distro, early_exit, history_log, image_id, instance_type, log_level, provider_config, region, results_dir, running_instance_id, secret_access_key, ssh_key_name, ssh_private_key, ssh_user, storage_container, provider, tests):
    try:
        (status, results) = test_image(provider, access_key_id, account, cleanup, config, distro, early_exit, history_log, image_id, instance_type, log_level, provider_config, region, results_dir, running_instance_id, secret_access_key, ssh_key_name, ssh_private_key, ssh_user, storage_container, tests)
        print(results)
        sys.exit(status)
    except Exception as error:
        if log_level == logging.DEBUG:
            raise
        click.secho('{}: {}'.format(type(error).__name__, error), fg='red')
        sys.exit(1)

def heartbeat(self, context, node_id, callback_url, agent_version=None, agent_token=None, agent_verify_ca=None, agent_status=None, agent_status_message=None):
    LOG.debug('RPC heartbeat called for node %s', node_id)
    if agent_version is None and agent_status is None:
        LOG.error('Node %s transmitted no version information which indicates the agent is incompatible with the ironic services and must be upgraded.', node_id)
        raise exception.InvalidParameterValue(_('Agent did not transmit a version, and a version is required. Please update the agent being used.'))
    with task_manager.acquire(context, node_id, shared=True, purpose='heartbeat') as task:
        if not utils.is_agent_token_valid(task.node, agent_token):
            LOG.error('Invalid or missing agent_token received for node %(node)s', {'node': node_id})
            raise exception.InvalidParameterValue('Invalid or missing agent token received.')
        if CONF.agent.require_tls and callback_url and (not callback_url.startswith('https://')):
            LOG.error('Rejecting callback_url %(url)s for node %(node)s because it does not use TLS', {'url': callback_url, 'node': task.node.uuid})
            raise exception.InvalidParameterValue(_('TLS is required by configuration'))
        if agent_verify_ca:
            agent_verify_ca = utils.store_agent_certificate(task.node, agent_verify_ca)
        task.spawn_after(self._spawn_worker, task.driver.deploy.heartbeat, task, callback_url, agent_version, agent_verify_ca, agent_status, agent_status_message, _allow_reserved_pool=False)

def _GenerateGradleFile(entry, generator, build_vars, jinja_processor):
    deps_info = entry.DepsInfo()
    gradle = entry.Gradle()
    variables = {'sourceSetName': 'main', 'depCompileName': 'compile'}
    if deps_info['type'] == 'android_apk':
        target_type = 'android_apk'
    elif deps_info['type'] == 'java_library':
        if deps_info['is_prebuilt'] or deps_info['gradle_treat_as_prebuilt']:
            return None
        elif deps_info['requires_android']:
            target_type = 'android_library'
        else:
            target_type = 'java_library'
    elif deps_info['type'] == 'java_binary':
        if gradle['main_class'] == 'org.chromium.testing.local.JunitTestMain':
            target_type = 'android_junit'
            variables['sourceSetName'] = 'test'
            variables['depCompileName'] = 'testCompile'
        else:
            target_type = 'java_binary'
            variables['main_class'] = gradle['main_class']
    else:
        return None
    variables['target_name'] = os.path.splitext(deps_info['name'])[0]
    variables['template_type'] = target_type
    variables['use_gradle_process_resources'] = generator.use_gradle_process_resources
    source_properties = _ReadPropertiesFile(_RebasePath(os.path.join(build_vars['android_sdk_build_tools'], 'source.properties')))
    variables['build_tools_version'] = source_properties['Pkg.Revision']
    variables['compile_sdk_version'] = 'android-%s' % build_vars['android_sdk_version']
    variables['main'] = generator.Generate(entry)
    bootclasspath = gradle.get('bootclasspath')
    if bootclasspath:
        variables['bootclasspath'] = _RebasePath(bootclasspath)
    if entry.android_test_entry:
        variables['android_test'] = generator.Generate(entry.android_test_entry)
        for (key, value) in variables['android_test'].iteritems():
            if isinstance(value, list):
                variables['android_test'][key] = list(set(value) - set(variables['main'][key]))
    return jinja_processor.Render(_TemplatePath(target_type.split('_')[0]), variables)

def add_team_to_topic(user, topic_id):
    data_json = flask.request.json
    clean_data = clean_json_with_schema(create_topic_schema, data_json)
    team_id = clean_data.get('team_id')
    topic = v1_utils.verify_existence_and_get(topic_id, _TABLE)
    team_id = v1_utils.verify_existence_and_get(team_id, models.TEAMS, get_id=True)
    if user.is_not_super_admin() and user.is_not_epm():
        raise dci_exc.Unauthorized()
    values = {'topic_id': topic['id'], 'team_id': team_id}
    query = models.JOINS_TOPICS_TEAMS.insert().values(**values)
    try:
        flask.g.db_conn.execute(query)
    except sa_exc.IntegrityError:
        raise dci_exc.DCICreationConflict(models.JOINS_TOPICS_TEAMS.name, 'team_id, topic_id')
    result = json.dumps(values)
    return flask.Response(result, 201, content_type='application/json')

def k8s_install_kubelogin(cmd, client_version='latest', install_location=None, source_url=None):
    cloud_name = cmd.cli_ctx.cloud.name
    if not source_url:
        source_url = 'https://github.com/Azure/kubelogin/releases/download'
        if cloud_name.lower() == 'azurechinacloud':
            source_url = 'https://mirror.azure.cn/kubernetes/kubelogin'
    if client_version == 'latest':
        context = _ssl_context()
        latest_release_url = 'https://api.github.com/repos/Azure/kubelogin/releases/latest'
        if cloud_name.lower() == 'azurechinacloud':
            latest_release_url = 'https://mirror.azure.cn/kubernetes/kubelogin/latest'
        latest_release = urlopen(latest_release_url, context=context).read()
        client_version = json.loads(latest_release)['tag_name'].strip()
    else:
        client_version = "v%s" % client_version
    base_url = source_url + '/{}/kubelogin.zip'
    file_url = base_url.format(client_version)
    install_dir, cli = os.path.dirname(
        install_location), os.path.basename(install_location)
    if not os.path.exists(install_dir):
        os.makedirs(install_dir)
    system = platform.system()
    if system == 'Windows':
        sub_dir, binary_name = 'windows_amd64', 'kubelogin.exe'
    elif system == 'Linux':
        if platform.machine() == 'arm64':
            sub_dir, binary_name = 'linux_arm64', 'kubelogin'
        else:
            sub_dir, binary_name = 'linux_amd64', 'kubelogin'
    elif system == 'Darwin':
        if platform.machine() == 'arm64':
            sub_dir, binary_name = 'darwin_arm64', 'kubelogin'
        else:
            sub_dir, binary_name = 'darwin_amd64', 'kubelogin'
    else:
        raise CLIError(
            'Proxy server ({}) does not exist on the cluster.'.format(system))
    with tempfile.TemporaryDirectory() as tmp_dir:
        try:
            download_path = os.path.join(tmp_dir, 'kubelogin.zip')
            logger.warning('Downloading client to "%s" from "%s",
                           download_path, file_url)
            _urlretrieve(file_url, download_path)
        except IOError as ex:
            raise CLIError(
                'Connection error while attempting to download client ({})'.format(ex))
        _unzip(download_path, tmp_dir)
        download_path = os.path.join(tmp_dir, 'bin', sub_dir, binary_name)
        shutil.move(download_path, install_location)
    os.chmod(install_location, os.stat(install_location).st_mode |
             stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
    if system == 'Windows':
        env_paths = os.environ['PATH'].split(';')
        found = next((x for x in env_paths if x.lower().rstrip(
            '\') == install_dir.lower()), None)
        if not found:
            logger.warning('Please add "{0}" to your search PATH so the `{1}` can be found. 2 options: \n'
                           '    1. Run "set PATH=%PATH%;{0}" or "$env:path += '{0}'" for PowerShell. '
                           'This is good for the current command session.\n'
                           '    2. Update system PATH environment variable by following '
                           '"Control Panel->System->Advanced->Environment Variables", and re-open the command window. '
                           'You only need to do it once'.format(install_dir, cli))
    else:
        logger.warning('Please ensure that %s is in your search PATH, so the `%s` command can be found.',
                       install_dir, cli)

