def feed_group(self, group: list, status_: str) -> None:
    ration_prey = get_clan_setting('ration_prey')
    for cat in group:
        feeding_amount = PREY_REQUIREMENT[status_]
        needed_amount = feeding_amount
        if cat.is_ill() or cat.is_injured():
            feeding_amount += CONDITION_INCREASE
            needed_amount = feeding_amount
        elif ration_prey and status_ == 'warrior':
            feeding_amount = feeding_amount / 2
        lot_more_prey = self.amount_food_needed() < self.total_amount * 1.5
        if lot_more_prey and self.nutrition_info[cat.ID].percentage < 100:
            feeding_amount += 1
        self.feed_cat(cat, feeding_amount, needed_amount)

def getposts(basequery=None, pinned=False, showall=False, statuses=None):
    if not statuses:
        statuses = POSTSTATUS.LISTED
    if basequery is None:
        basequery = JobPost.query
    query = basequery.filter(JobPost.status.in_(statuses)).options(*JobPost._defercols)
    if showall:
        query = query.filter(JobPost.datetime > datetime.utcnow() - agelimit)
    elif pinned:
        if g.board:
            query = query.join(JobPost.postboards).filter(BoardJobPost.board == g.board).filter(db.or_(db.and_(JobPost.pinned == True, JobPost.datetime > datetime.utcnow() - agelimit), db.and_(JobPost.pinned == False, JobPost.datetime > datetime.utcnow() - newlimit)))
        else:
            query = query.filter(db.or_(db.and_(JobPost.pinned == True, JobPost.datetime > datetime.utcnow() - agelimit), db.and_(JobPost.pinned == False, JobPost.datetime > datetime.utcnow() - newlimit)))
    else:
        query = query.filter(JobPost.datetime > datetime.utcnow() - newlimit)
    if g.board and g.board.name != u'www':
        query = query.join(JobPost.postboards).filter(BoardJobPost.board == g.board)
    if pinned:
        if g.board:
            query = query.order_by(db.desc(BoardJobPost.pinned))
        else:
            query = query.order_by(db.desc(JobPost.pinned))
    return query.order_by(db.desc(JobPost.datetime))

