def _overlay_mask(image, mask, alpha=0.6):
    assert image.ndim in (2, 3)
    if image.ndim == 2:
        overlay = np.stack([image, image, image]).transpose((1, 2, 0))
    else:
        overlay = image
    assert overlay.shape[-1] == 3
    mask_overlay = np.zeros_like(overlay)
    mask_overlay[mask == 1] = [255, 0, 0]
    overlay = alpha * overlay + (1.0 - alpha) * mask_overlay
    return overlay.astype('uint8')

def redirect_escalations(cls, bundles: Generator[TrendBundle, None, None], timestamp: datetime, batch_size=100) -> Generator[TrendBundle, None, None]:
    groups_to_escalate = []
    for bundle in bundles:
        group = bundle.regression_group
        try:
            if group is not None and bundle.state is not None and bundle.state.should_escalate(group.baseline, group.regressed, cls.min_change, cls.escalation_rel_threshold):
                groups_to_escalate.append(group)
            yield bundle
        except Exception as e:
            sentry_sdk.capture_exception(e)
    for group in groups_to_escalate:
        group.status = GroupStatus.ESCALATED
        group.save()
    metrics.incr('statistical_detectors.objects.escalated', amount=len(groups_to_escalate), tags={'source': cls.source, 'kind': cls.kind}, sample_rate=1.0)

from jsonschema import validate, ValidationError
    def add_nio(self, request):
        if request is None:
            self.send_param_error()
            return
        schema = {
            "type": "object",
            "properties": {
                "id": {"type": "string"},
                "slot": {"type": "integer"},
                "port": {"type": "integer"},
                "port_id": {"type": "string"},
                "nio": {"type": "string", "enum": ["NIO_UDP", "NIO_GenericEthernet", "NIO_TAP"]},
                "lport": {"type": "integer"},
                "rhost": {"type": "string"},
                "rport": {"type": "integer"},
                "ethernet_device": {"type": "string"},
                "tap_device": {"type": "string"}
            },
            "required": ["id", "slot", "port", "nio"],
            "additionalProperties": False,
            "allOf": [
                {
                    "if": {"properties": {"nio": {"const": "NIO_UDP"}}},
                    "then": {"required": ["lport", "rhost", "rport"]}
                },
                {
                    "if": {"properties": {"nio": {"const": "NIO_GenericEthernet"}}},
                    "then": {"required": ["ethernet_device"]}
                },
                {
                    "if": {"properties": {"nio": {"const": "NIO_TAP"}}},
                    "then": {"required": ["tap_device"]}
                }
            ]
        }
        try:
            validate(instance=request, schema=schema)
        except ValidationError as e:
            self.send_param_error()
            return
        log.debug("received request {}".format(request))
        iou_id = request["id"]
        if iou_id not in self._iou_instances:
            self.send_custom_error("IOU device id {} doesn't exist".format(iou_id))
            return
        iou_instance = self._iou_instances[iou_id]
        slot = request["slot"]
        port = request["port"]
        try:
            nio = None
            if request["nio"] == "NIO_UDP":
                lport = request["lport"]
                rhost = request["rhost"]
                rport = request["rport"]
                nio = NIO_UDP(lport, rhost, rport)
            elif request["nio"] == "NIO_TAP":
                tap_device = request["tap_device"]
                nio = NIO_TAP(tap_device)
            elif request["nio"] == "NIO_GenericEthernet":
                ethernet_device = request["ethernet_device"]
                nio = NIO_GenericEthernet(ethernet_device)
            if not nio:
                raise IOUError("Requested NIO doesn't exist or is not supported: {}".format(request["nio"]))
        except IOUError as e:
            self.send_custom_error(str(e))
            return
        try:
            iou_instance.slot_add_nio_binding(slot, port, nio)
        except IOUError as e:
            self.send_custom_error(str(e))
            return
        self.send_response(request)

def _build_log_files_from_dictionary(self, list_of_logs_in_dictionaries):
    loglist = {}
    for log in list_of_logs_in_dictionaries:
        try:
            loglist[log['name']] = LogFile(log['maxdepth'], log['name'], log['timestamp'], log['binsize'], self.ip)
        except dateutil.parser.ParserError:
            logger.warning(f"Could not parse timestamp for log {log['name']}, skipping this log file")
    return loglist

def __init__(self, *args):
    if len(args) == 3 and callable(args[2]):
        operation = args[2]
        self.rows = int(args[0])
        self.cols = int(args[1])
        self.mat = []
        for i in range(self.rows):
            for j in range(self.cols):
                self.mat.append(sympify(operation(i, j)))
    elif len(args) == 3 and isinstance(args[2], (list, tuple)):
        self.rows = args[0]
        self.cols = args[1]
        mat = args[2]
        if len(mat) != self.rows * self.cols:
            raise MatrixError('List length should be equal to rows*columns')
        self.mat = map(lambda i: sympify(i), mat)
    elif len(args) == 1:
        mat = args[0]
        if isinstance(mat, Matrix):
            self.rows = mat.rows
            self.cols = mat.cols
            self.mat = mat[:]
            return
        elif hasattr(mat, '__array__'):
            arr = mat.__array__()
            if len(arr.shape) == 2:
                (self.rows, self.cols) = (arr.shape[0], arr.shape[1])
                self.mat = map(lambda i: sympify(i), arr.ravel())
                return
            elif len(arr.shape) == 1:
                (self.rows, self.cols) = (1, arr.shape[0])
                self.mat = [0] * self.cols
                for i in xrange(len(arr)):
                    self.mat[i] = sympify(arr[i])
                return
            else:
                raise NotImplementedError('Sympy supports just 1D and 2D matrices')
        elif not isinstance(mat, (list, tuple)):
            raise TypeError("Matrix constructor doesn't accept %s as input" % str(type(mat)))
        self.rows = len(mat)
        if len(mat) != 0:
            if not isinstance(mat[0], (list, tuple)):
                self.cols = 1
                self.mat = map(lambda i: sympify(i), mat)
                return
            self.cols = len(mat[0])
        else:
            self.cols = 0
        self.mat = []
        for j in xrange(self.rows):
            assert len(mat[j]) == self.cols
            for i in xrange(self.cols):
                self.mat.append(sympify(mat[j][i]))
    elif len(args) == 0:
        self.rows = self.cols = 0
        self.mat = []
    else:
        raise TypeError('Data type not understood')

def __init__(self, *args):
    if len(args) == 3 and callable(args[2]):
        operation = args[2]
        self.rows = int(args[0])
        self.cols = int(args[1])
        self.mat = []
        for i in range(self.rows):
            for j in range(self.cols):
                self.mat.append(sympify(operation(i, j)))
    elif len(args) == 3 and isinstance(args[2], (list, tuple)):
        self.rows = args[0]
        self.cols = args[1]
        mat = args[2]
        if len(mat) != self.rows * self.cols:
            raise MatrixError('List length should be equal to rows*columns')
        self.mat = map(lambda i: sympify(i), mat)
    elif len(args) == 1:
        mat = args[0]
        if isinstance(mat, Matrix):
            self.rows = mat.rows
            self.cols = mat.cols
            self.mat = mat[:]
            return
        elif hasattr(mat, '__array__'):
            arr = mat.__array__()
            if len(arr.shape) == 2:
                (self.rows, self.cols) = (arr.shape[0], arr.shape[1])
                self.mat = map(lambda i: sympify(i), arr.ravel())
                return
            elif len(arr.shape) == 1:
                (self.rows, self.cols) = (1, arr.shape[0])
                self.mat = [0] * self.cols
                for i in xrange(len(arr)):
                    self.mat[i] = sympify(arr[i])
                return
            else:
                raise NotImplementedError('Sympy supports just 1D and 2D matrices')
        elif not isinstance(mat, (list, tuple)):
            raise TypeError("Matrix constructor doesn't accept %s as input" % str(type(mat)))
        self.rows = len(mat)
        if len(mat) != 0:
            if not isinstance(mat[0], (list, tuple)):
                self.cols = 1
                self.mat = map(lambda i: sympify(i), mat)
                return
            self.cols = len(mat[0])
        else:
            self.cols = 0
        self.mat = []
        for j in xrange(self.rows):
            assert len(mat[j]) == self.cols
            for i in xrange(self.cols):
                self.mat.append(sympify(mat[j][i]))
    elif len(args) == 0:
        self.rows = self.cols = 0
        self.mat = []
    else:
        raise TypeError('Data type not understood')

def _validate_common(self, task):
    node = task.node
    if not driver_utils.get_node_mac_addresses(task):
        raise exception.MissingParameterValue(_('Node %s does not have any port associated with it.') % node.uuid)
    deploy_utils.validate_capabilities(node)
    if deploy_utils.is_trusted_boot_requested(node):
        validate_boot_parameters_for_trusted_boot(node)
    pxe_utils.parse_driver_info(node)

def load_defaults_configuration(self, silent=False):
    for (option, value) in utils.get_global_settings().items():
        setattr(self.parameters, option, value)
    setattr(self.parameters, 'destination_pipeline_host', os.getenv('INTELMQ_DESTINATION_PIPELINE_HOST', '127.0.0.1'))
    setattr(self.parameters, 'source_pipeline_host', os.getenv('INTELMQ_SOURCE_PIPELINE_HOST', '127.0.0.1'))
    if os.getenv('INTELMQ_IS_DOCKER', None):
        pipeline_host = os.getenv('INTELMQ_PIPELINE_HOST')
        if pipeline_host:
            setattr(self.parameters, 'destination_pipeline_host', pipeline_host)
            setattr(self.parameters, 'source_pipeline_host', pipeline_host)

def maybe_adjust_fees(plugin: Plugin, scids: list):
    channels_adjusted = 0
    for scid in scids:
        if scid in plugin.exclude_list or get_peer_id_for_scid(plugin, scid) in plugin.exclude_list:
            continue
        our = plugin.adj_balances[scid]['our']
        total = plugin.adj_balances[scid]['total']
        percentage = our / total
        base = int(plugin.adj_basefee)
        ppm = int(plugin.adj_ppmfee)
        fees = plugin.fee_strategy(plugin, scid)
        if fees is not None:
            ppm = int(fees['ppm'])
            if plugin.basefee:
                base = int(fees['base'])
        if percentage > plugin.imbalance and percentage < 1 - plugin.imbalance:
            if setchannelfee(plugin, scid, base, ppm):
                plugin.log(f'Set default fees as imbalance is too low for {scid}:   ppm {ppm}   base {base}msat')
                plugin.adj_balances[scid]['last_liquidity'] = our
                channels_adjusted += 1
            continue
        if not significant_update(plugin, scid):
            continue
        percentage = get_adjusted_percentage(plugin, scid)
        assert 0 <= percentage and percentage <= 1, f'percentage is out of bounds: balances: {plugin.adj_balances[scid]} big_enough_liquidity: {int(plugin.big_enough_liquidity)}'
        ratio = plugin.get_ratio(percentage)
        if plugin.max_htlc_steps >= 1:
            max_htlc = int(total * math.ceil(plugin.max_htlc_steps * percentage) / plugin.max_htlc_steps)
        else:
            max_htlc = None
        if setchannelfee(plugin, scid, base, int(ppm * ratio), None, max_htlc):
            plugin.log(f'Adjusted fees of {scid} with a ratio of {ratio}:   ppm {int(ppm * ratio)}   base {base}msat   max_htlc {max_htlc}')
            plugin.adj_balances[scid]['last_liquidity'] = our
            channels_adjusted += 1
    plugin.log('maybe_adjust_fees done', 'debug')
    return channels_adjusted

