def send_msg(msg, server='localhost', port='6667', channel=None, nick_to=None, key=None, topic=None, nick='ansible', color='none', passwd=False, timeout=30, use_ssl=False, part=True, style=None):
    nick_to = [] if nick_to is None else nick_to
    colornumbers = {'white': '00', 'black': '01', 'blue': '02', 'green': '03', 'red': '04', 'brown': '05', 'purple': '06', 'orange': '07', 'yellow': '08', 'light_green': '09', 'teal': '10', 'light_cyan': '11', 'light_blue': '12', 'pink': '13', 'gray': '14', 'light_gray': '15'}
    stylechoices = {'bold': '\x02', 'underline': '\x1f', 'reverse': '\x16', 'italic': '\x1d'}
    try:
        styletext = stylechoices[style]
    except Exception:
        styletext = ''
    try:
        colornumber = colornumbers[color]
        colortext = '\x03' + colornumber
    except Exception:
        colortext = ''
    message = styletext + colortext + msg
    irc = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    if use_ssl:
        if getattr(ssl, 'PROTOCOL_TLS', None) is not None:
            context = ssl.create_default_context()
        else:
            context = ssl.SSLContext()
        context.verify_mode = ssl.CERT_NONE
        irc = context.wrap_socket(irc)
    irc.connect((server, int(port)))
    if passwd:
        irc.send(to_bytes('PASS %s\r\n' % passwd))
    irc.send(to_bytes('NICK %s\r\n' % nick))
    irc.send(to_bytes('USER %s %s %s :ansible IRC\r\n' % (nick, nick, nick)))
    motd = ''
    start = time.time()
    while 1:
        motd += to_native(irc.recv(1024))
        match = re.search('^:\\S+ 00[1-4] (?P<nick>\\S+) :', motd, flags=re.M)
        if match:
            nick = match.group('nick')
            break
        elif time.time() - start > timeout:
            raise Exception('Timeout waiting for IRC server welcome response')
        time.sleep(0.5)
    if channel:
        if key:
            irc.send(to_bytes('JOIN %s %s\r\n' % (channel, key)))
        else:
            irc.send(to_bytes('JOIN %s\r\n' % channel))
        join = ''
        start = time.time()
        while 1:
            join += to_native(irc.recv(1024))
            if re.search('^:\\S+ 366 %s %s :' % (nick, channel), join, flags=re.M | re.I):
                break
            elif time.time() - start > timeout:
                raise Exception('Timeout waiting for IRC JOIN response')
            time.sleep(0.5)
        if topic is not None:
            irc.send(to_bytes('TOPIC %s :%s\r\n' % (channel, topic)))
            time.sleep(1)
    if nick_to:
        for nick in nick_to:
            irc.send(to_bytes('PRIVMSG %s :%s\r\n' % (nick, message)))
    if channel:
        irc.send(to_bytes('PRIVMSG %s :%s\r\n' % (channel, message)))
    time.sleep(1)
    if part:
        if channel:
            irc.send(to_bytes('PART %s\r\n' % channel))
        irc.send(to_bytes('QUIT\r\n'))
        time.sleep(1)
    irc.close()

def excerpt(self, source_paths, workdir, conform):
    encoding = conform.get('encoding')
    csvsplit = conform.get('csvsplit', ',')
    known_paths = ExcerptDataTask._get_known_paths(source_paths, workdir, conform, self.known_types)
    if not known_paths:
        return (None, None)
    data_path = known_paths[0]
    (_, data_ext) = os.path.splitext(data_path.lower())
    if data_ext in ('.geojson', '.json'):
        data_path = ExcerptDataTask._sample_geojson_file(data_path)
    format_string = conform.get('format')
    if format_string == 'csv':
        return ExcerptDataTask._excerpt_csv_file(data_path, encoding, csvsplit)
    ogr_data_path = normalize_ogr_filename_case(data_path)
    datasource = ogr.Open(ogr_data_path, 0)
    layer = datasource.GetLayer()
    if not encoding:
        encoding = guess_source_encoding(datasource, layer)
    if data_ext == '.csv' and encoding not in ('utf8', 'utf-8'):
        return ExcerptDataTask._excerpt_csv_file(data_path, encoding, csvsplit)
    layer_defn = layer.GetLayerDefn()
    fieldcount = layer_defn.GetFieldCount()
    fieldnames = [layer_defn.GetFieldDefn(i).GetName() for i in range(fieldcount)]
    fieldnames = [f.decode(encoding) if hasattr(f, 'decode') else f for f in fieldnames]
    data_sample = [fieldnames]
    for (feature, _) in zip(layer, range(5)):
        row = [feature.GetField(i) for i in range(fieldcount)]
        row = [v.decode(encoding) if hasattr(v, 'decode') else v for v in row]
        data_sample.append(row)
    if len(data_sample) < 2:
        raise ValueError('Not enough rows in data source')
    if layer_defn.GetGeomType() in geometry_types:
        geometry_type = geometry_types.get(layer_defn.GetGeomType(), None)
    elif fieldnames[-3:] == [X_FIELDNAME, Y_FIELDNAME, GEOM_FIELDNAME]:
        geometry = ogr.CreateGeometryFromWkt(data_sample[1][-1])
        geometry_type = geometry_types.get(geometry.GetGeometryType(), None)
    else:
        geometry_type = None
    return (data_sample, geometry_type)

