def __init__(self, model: openvino.runtime.Model, parent_model: OVBaseModel, ov_config: Optional[Dict[str, str]]=None, model_name: str='encoder', model_dir: str=None):
    self.model = model
    self.parent_model = parent_model
    self.input_names = {key.get_any_name(): idx for (idx, key) in enumerate(self.model.inputs)}
    self.input_dtype = {inputs.get_any_name(): OV_TO_NP_TYPE[inputs.get_element_type().get_type_name()] for inputs in self.model.inputs}
    self.ov_config = ov_config or {**self.parent_model.ov_config}
    self.request = None
    self._model_name = model_name
    self._model_dir = Path(model_dir or parent_model._model_save_dir)
    config_path = self._model_dir / model_name / self.CONFIG_NAME
    self.config = self.parent_model._dict_from_json_file(config_path) if config_path.is_file() else {}
    if self._model_dir.is_dir() and str(self._model_dir).startswith(gettempdir()):
        return
    if 'CACHE_DIR' not in self.ov_config:
        self.ov_config['CACHE_DIR'] = os.path.join(self._model_dir, self._model_name)

def validateTexturePath(path):
    path = expand_path(path)
    if not os.path.exists(path):
        raise ValidationException('%r does not exist.' % path)
    return path

def update(self, **kwargs):
    if self.can_update:
        project_update = self.project_updates.create(**kwargs)
        if hasattr(settings, 'CELERY_UNIT_TEST'):
            project_update.start(None, **kwargs)
        else:
            project_update.signal_start(**kwargs)
        return project_update

def on_task_metainfo(self, task, config):
    for entry in task.entries:
        entry['_backlog_snapshot'] = serialize(entry)

def on_task_metainfo(self, task, config):
    for entry in task.entries:
        entry['_backlog_snapshot'] = serialize(entry)

def update_tool(db: Session, tool: Tool, patch_tool: t.Union[CreateTool, PatchToolDockerimage]) -> Tool:
    if isinstance(patch_tool, CreateTool):
        tool.name = patch_tool.name
    elif patch_tool.persistent:
        tool.docker_image_template = patch_tool.persistent
        tool.readonly_image = patch_tool.readonly
    db.add(tool)
    db.commit()
    return tool

def _update_job(self, job_id, state=None, **kwargs):
    with self.session_scope() as session:
        try:
            (job, orm_job) = self._get_job_and_orm_job(job_id, session)
            job_copy = copy(job)
            if state is not None:
                job_copy.state = state
            for (kwarg, value) in kwargs.items():
                setattr(job_copy, kwarg, value)
            orm_job.obj = job_copy
            session.add(orm_job)
            return (job_copy, orm_job)
        except JobNotFound:
            if state:
                logger.error('Tried to update job with id {} with state {} but it was not found'.format(job_id, state))
            else:
                logger.error('Tried to update job with id {} but it was not found'.format(job_id))

def _generateColumnHeader(self, obj, **args):
    result = []
    # Do not return yourself as a header.
    #
    try:
        role = args.get('role', obj.getRole())
    except:
        role = None
    if role in [pyatspi.ROLE_COLUMN_HEADER,
                pyatspi.ROLE_TABLE_COLUMN_HEADER]:
        return result
    try:
        table = obj.parent.queryTable()
    except:
        pass
    else:
        index = self._script.utilities.cellIndex(obj)
        columnIndex = table.getColumnAtIndex(index)
        if columnIndex >= 0:
            # Get the header information.  In Java Swing, the
            # information is not exposed via the description
            # but is instead a header object, so we fall back
            # to that if it exists.
            #
            desc = table.getColumnHeader(columnIndex)
            if desc:
                header = desc
            else:
                header = table.getColumnDescription(columnIndex)
                if header:
                    header = self._script.utilities.displayedText(header)
            if header and len(header):
                text = header
                if args['mode'] == 'speech':
                    if settings.speechVerbosityLevel
                       == settings.VERBOSITY_LEVEL_VERBOSE
                       and not args.get('formatType', None)
                               in ['basicWhereAmI', 'detailedWhereAmI']:
                        text = header + " " + self.getLocalizedRoleName(
                            obj, pyatspi.ROLE_COLUMN_HEADER)
                elif args['mode'] == 'braille':
                    text = header + " " + self.getLocalizedRoleName(
                        obj, pyatspi.ROLE_COLUMN_HEADER)
                result.append(text)
    return result

def decrypt(self):
    current_encryption_context = self.parameters.get('EncryptionContext')
    stored_encryption_context = self.kms_backend.get_stored_encryption_context()
    if current_encryption_context != stored_encryption_context:
        raise ValidationException('EncryptionContext does not match. Refusing to decode.')
    value = self.parameters.get('CiphertextBlob')
    try:
        return json.dumps({'Plaintext': base64.b64decode(value).decode('utf-8'), 'KeyId': 'key_id'})
    except UnicodeDecodeError:
        return json.dumps({'Plaintext': value})

def genome_map(_input, max_wraps=0):
    from utilities.helper_methods import python_filter
    (used_input, current_depth, current_max_depth, nodes) = (0, 0, 0, 1)
    (wraps, output, production_choices) = (-1, [], [])
    unexpanded_symbols = [(params['BNF_GRAMMAR'].start_rule, 0)]
    while wraps < max_wraps and len(unexpanded_symbols) > 0 and (current_max_depth <= params['MAX_TREE_DEPTH']):
        if used_input % len(_input) == 0 and used_input > 0 and any([i[0][1] == 'NT' for i in unexpanded_symbols]):
            wraps += 1
        current_item = unexpanded_symbols.pop(0)
        (current_symbol, current_depth) = (current_item[0], current_item[1])
        if current_max_depth < current_depth:
            current_max_depth = current_depth
        if current_symbol[1] != params['BNF_GRAMMAR'].NT:
            output.append(current_symbol[0])
        else:
            production_choices = params['BNF_GRAMMAR'].rules[current_symbol[0]]
            current_production = _input[used_input % len(_input)] % len(production_choices)
            used_input += 1
            children = []
            for prod in production_choices[current_production]:
                children.append([prod, current_depth + 1])
            NT_kids = [child for child in children if child[0][1] == 'NT']
            if any(NT_kids):
                nodes += len(NT_kids)
            else:
                nodes += 1
            unexpanded_symbols = children + unexpanded_symbols
    if len(unexpanded_symbols) > 0:
        return (output, _input, None, nodes, True, current_max_depth + 1, used_input)
    output = ''.join(output)
    if params['BNF_GRAMMAR'].python_mode:
        output = python_filter(output)
    return (output, _input, None, nodes, False, current_max_depth + 1, used_input)

