def _decode_to(cls: Type[T], raw_rlp: RLP) -> T:
    if isinstance(cls, type(Tuple[Uint, ...])) and cls._name == 'Tuple':
        ensure(type(raw_rlp) == list, RLPDecodingError)
        if cls.__args__[1] == ...:
            args = []
            for raw_item in raw_rlp:
                args.append(_decode_to(cls.__args__[0], raw_item))
            return tuple(args)
        else:
            args = []
            for (t, raw_item) in zip(cls.__args__, raw_rlp):
                args.append(_decode_to(t, raw_item))
            return tuple(args)
    elif cls == Union[Bytes0, Bytes20]:
        ensure(type(raw_rlp) == Bytes, RLPDecodingError)
        if len(raw_rlp) == 0:
            return Bytes0()
        elif len(raw_rlp) == 20:
            return Bytes20(raw_rlp)
        else:
            raise RLPDecodingError('RLP Decoding to type {} is not supported'.format(cls))
    elif isinstance(cls, type(List[Bytes])) and cls._name == 'List':
        ensure(type(raw_rlp) == list, RLPDecodingError)
        items = []
        for raw_item in raw_rlp:
            items.append(_decode_to(cls.__args__[0], raw_item))
        return items
    elif isinstance(cls, type(Union[Bytes, List[Bytes]])) and cls.__origin__ == Union:
        if len(cls.__args__) != 2 or Bytes not in cls.__args__:
            raise RLPDecodingError('RLP Decoding to type {} is not supported'.format(cls))
        if isinstance(raw_rlp, Bytes):
            return raw_rlp
        elif cls.__args__[0] == Bytes:
            return _decode_to(cls.__args__[1], raw_rlp)
        else:
            return _decode_to(cls.__args__[0], raw_rlp)
    elif issubclass(cls, bool):
        if raw_rlp == b'\x01':
            return cls(True)
        elif raw_rlp == b'':
            return cls(False)
        else:
            raise TypeError('Cannot decode {} as {}'.format(raw_rlp, cls))
    elif issubclass(cls, Bytes):
        ensure(type(raw_rlp) == Bytes, RLPDecodingError)
        return raw_rlp
    elif issubclass(cls, (Uint, U256, Uint64)):
        ensure(type(raw_rlp) == Bytes, RLPDecodingError)
        return cls.from_be_bytes(raw_rlp)
    elif is_dataclass(cls):
        ensure(type(raw_rlp) == list, RLPDecodingError)
        assert isinstance(raw_rlp, list)
        args = []
        if len(raw_rlp) != len(fields(cls)):
            raise RLPDecodingError('Length of raw_rlp does not match number of fields in dataclass {}'.format(cls))
        for (field, rlp_item) in zip(fields(cls), raw_rlp):
            args.append(_decode_to(field.type, rlp_item))
        return cls(*args)
    else:
        raise RLPDecodingError('RLP Decoding to type {} is not supported'.format(cls))

def exports(self):
    from pyflyby._importclns import ImportStatement, ImportSet
    import ast
    module = self.module
    try:
        members = module.__all__
    except AttributeError:
        members = dir(module)
        members = [n for n in members if not n.startswith('_')]

        def from_this_module(name):
            x = getattr(module, name)
            m = getattr(x, '__module__', None)
            if not m:
                return False
            return DottedIdentifier(m).startswith(self.name)
        members = [n for n in members if from_this_module(n)]
    else:
        if not all((type(s) == str for s in members)):
            raise Exception('Module %r contains non-string entries in __all__' % (str(self.name),))
    members = [(n, None) for n in members if '.' not in n]
    if not members:
        return None
    return ImportSet([ImportStatement.from_parts(str(self.name), members)])

def exports(self):
    from pyflyby._importclns import ImportStatement, ImportSet
    import ast
    module = self.module
    try:
        members = module.__all__
    except AttributeError:
        members = dir(module)
        members = [n for n in members if not n.startswith('_')]

        def from_this_module(name):
            source = ast.get_source_segment(inspect.getsource(module), module)
            tree = ast.parse(source)
            for node in ast.walk(tree):
                if isinstance(node, ast.Assign):
                    for target in node.targets:
                        if isinstance(target, ast.Name) and target.id == name:
                            return True
            return False
        members = [n for n in members if from_this_module(n)]
    else:
        if not all((type(s) == str for s in members)):
            raise Exception('Module %r contains non-string entries in __all__' % (str(self.name),))
    members = [(n, None) for n in members if '.' not in n]
    if not members:
        return None
    return ImportSet([ImportStatement.from_parts(str(self.name), members)])

def visit_Data_Implied_Do(self, o, **kwargs):
    loop_var = o.children[0]
    range_expr = o.children[1]
    ir_loop = ir.ImpliedDo(loop_var=loop_var, range=range_expr)
    return self.visit(ir_loop, **kwargs)

def process_dependencies(self, task, deplist, uowcommit, delete=False):
    if delete:
        if not self.cascade.delete_orphan or self.post_update:
            for obj in deplist:
                childlist = self.get_object_dependencies(obj, uowcommit, passive=self.passive_deletes)
                if childlist is not None:
                    for child in childlist.deleted_items():
                        if child is not None and childlist.hasparent(child) is False:
                            self._synchronize(obj, child, None, True, uowcommit)
                            self._conditional_post_update(child, uowcommit, [obj])
                    for child in childlist.unchanged_items():
                        if child is not None:
                            self._synchronize(obj, child, None, True, uowcommit)
                            self._conditional_post_update(child, uowcommit, [obj])
    else:
        for obj in deplist:
            childlist = self.get_object_dependencies(obj, uowcommit, passive=True)
            if childlist is not None:
                for child in childlist.added_items():
                    self._synchronize(obj, child, None, False, uowcommit)
                    self._conditional_post_update(child, uowcommit, [obj])
                for child in childlist.deleted_items():
                    if not self.cascade.delete_orphan and (not self._get_instrumented_attribute().hasparent(child)):
                        self._synchronize(obj, child, None, True, uowcommit)

def dict_for_mongo(_dict):
    for (key, value) in _dict.items():
        if _is_invalid_for_mongo(key):
            del _dict[key]
            key = key_for_mongo(key)
        if isinstance(value, list):
            _dict[key] = [dict_for_mongo(obj) if isinstance(obj, dict) else obj for obj in value]
        elif isinstance(value, dict):
            _dict[key] = dict_for_mongo(value)
        else:
            _dict[key] = value_for_mongo(value)
    return _dict

def value_for_mongo(value):
    if isinstance(value, datetime64):
        return str(value)
    return value

def mbox_uuid(self):
    if self.mbox_wrapper is None:
        raise RuntimeError('This is not a mailbox collection')
    return self.mbox_wrapper.uuid

def method(self, methodId, objId, className, methodName, args=None, packageName='qpid'):
    codec = Codec(StringIO(), self.spec)
    codec.encode_long(methodId)
    codec.encode_longlong(objId)
    codec.encode_shortstr(self.rqname)
    if args is not None:
        if className not in self.schema:
            raise ValueError('Unknown class name: %s' % className)
        schemaClass = self.schema[className]
        ms = schemaClass['M']
        arglist = None
        for mname in ms:
            (mdesc, margs) = ms[mname]
            if mname == methodName:
                arglist = margs
        if arglist is None:
            raise ValueError('Unknown method name: %s' % methodName)
        for arg in arglist:
            if arg[2].find('I') != -1:
                value = arg[8]
                if arg[0] in args:
                    value = args[arg[0]]
                    if value is None:
                        raise ValueError('Missing non-defaulted argument: %s' % arg[0])
                self.encodeValue(codec, value, arg[1])
    msg = Content(codec.stream.getvalue())
    msg['content_type'] = 'application/octet-stream'
    msg['routing_key'] = 'method.' + packageName + '.' + className + '.' + methodName
    msg['reply_to'] = self.spec.struct('reply_to')
    self.channel.message_transfer(destination='qpid.management', content=msg)

def _validate_requested_port_ids(self, context, instance, neutron, requested_networks):
    ports = {}
    ordered_networks = []
    if requested_networks and (not requested_networks.auto_allocate):
        for request in requested_networks:
            if request.port_id:
                port = self._show_port(context, request.port_id, neutron_client=neutron)
                if port['tenant_id'] != instance.project_id:
                    raise exception.PortNotUsable(port_id=request.port_id, instance=instance.uuid)
                if port.get('device_id'):
                    raise exception.PortInUse(port_id=request.port_id)
                if port.get('dns_name'):
                    if port['dns_name'] != instance.hostname:
                        raise exception.PortNotUsableDNS(port_id=request.port_id, instance=instance.uuid, value=port['dns_name'], hostname=instance.hostname)
                _ensure_no_port_binding_failure(port)
                request.network_id = port['network_id']
                ports[request.port_id] = port
            if request.network_id:
                ordered_networks.append(request)
    return (ports, ordered_networks)

def reset(self, id: Optional[Union[int, List[int], np.ndarray]]=None) -> tuple[np.ndarray, np.ndarray]:
    (obs, info) = self.venv.reset(id)
    if self.obs_rms and self.update_obs_rms:
        self.obs_rms.update(obs)
    return (self._norm_obs(obs), info)

class PluginError(Exception):
    pass

def _close_plugin_instance(self, plugin):
    instance = self.plugins[plugin]['instance']
    module = self.plugins[plugin]['module']
    if hasattr(instance, 'close') and inspect.ismethod(instance.close):
        argspec = inspect.getfullargspec(instance.close)
        if len(argspec.args) == 1:
            instance.close()
        elif len(argspec.args) == 2:
            instance.close(self.cardinal)
        else:
            raise PluginError('Plugin close function may not have more than one argument')

def parse_attr(self, attr):

    def tilde_unescape(string):

        def repl(m):
            if m.group(1) == '1':
                return '/'
            elif m.group(1) == 'a':
                return ','
            elif m.group(1) == 'b':
                return '@'
        if string == '@key':
            return KeyAttribute()
        s1 = self.tildeEscape_re.sub(repl, string)
        return re.sub('~0', '~', s1)
    attrs = attr.split('/')
    return [tilde_unescape(a) for a in attrs]

def get(self, name: str) -> Compute:
    (response, rest_obj) = self._operation.get(self._operation_scope.resource_group_name, self._workspace_name, name, cls=get_http_response_and_deserialized_from_pipeline_response)
    response_json = json.loads(response.internal_response.text)
    xds_error_code = 'XDSRestartRequired'
    warnings = response_json['properties'].get('warnings', [])
    xds_warning = next((warning for warning in warnings if warning['code'] == xds_error_code), None)
    if xds_warning:
        logging.critical(xds_warning['message'])
    return Compute._from_rest_object(rest_obj)

def labels(self):
    codes = getattr(self.index, 'codes', None)
    if codes is None:
        codes = pd.Categorical(self.index).codes[None]
    return codes

@property
def labels(self):
    return self.index.codes

def run(self):
    spoke_portfolio_details = self.get_output_from_reference_dependency(self.portfolio_task_reference)
    spoke_portfolio_id = spoke_portfolio_details.get('Id')
    spoke_products_and_their_versions = self.get_output_from_reference_dependency(self.portfolio_get_all_products_and_their_versions_ref)
    hub_products_and_their_versions = self.get_output_from_reference_dependency(self.portfolio_get_all_products_and_their_versions_for_hub_ref)
    copy_product_tokens = list()
    versions_requiring_updates = dict()
    products_requiring_adding_to_portfolio = dict()
    with self.spoke_regional_client('servicecatalog') as servicecatalog:
        for (hub_product_name, hub_product_details) in hub_products_and_their_versions.items():
            versions_to_copy = list()
            args_to_use = dict(SourceProductArn=hub_product_details.get('ProductArn'), SourceProvisioningArtifactIdentifiers=versions_to_copy, CopyOptions=['CopyTags'])
            hub_versions_details = hub_product_details.get('Versions', {})
            if spoke_products_and_their_versions.get(hub_product_name):
                args_to_use['TargetProductId'] = spoke_products_and_their_versions.get(hub_product_name).get('ProductId')
            else:
                products_requiring_adding_to_portfolio[hub_product_name] = True
            spoke_product_details = spoke_products_and_their_versions.get(hub_product_name, {})
            spoke_versions_details = spoke_product_details.get('Versions', {})
            version_names_to_ignore = ['-'] + list(spoke_versions_details.keys())
            for (hub_version_name, hub_version_details) in hub_versions_details.items():
                if hub_version_name not in version_names_to_ignore:
                    versions_to_copy.append(dict(Id=hub_version_details.get('Id')))
                else:
                    if hub_version_name == '-':
                        continue
                    spoke_product_id = spoke_product_details['ProductId']
                    if not versions_requiring_updates.get(spoke_product_id):
                        versions_requiring_updates[spoke_product_id] = dict()
                    spoke_version_id = spoke_versions_details[hub_version_name]['Id']
                    versions_requiring_updates[spoke_product_id][spoke_version_id] = dict(Active=hub_version_details.get('Active'), Guidance=hub_version_details.get('Guidance'), Description=hub_version_details.get('Description'))
            if len(versions_to_copy) > 0:
                copy_product_tokens.append((hub_product_name, servicecatalog.copy_product(**args_to_use).get('CopyProductToken')))
        self.info('Finished copying products')
        while len(copy_product_tokens) > 0:
            first_item_in_list = copy_product_tokens[0]
            (product_name, copy_product_token_to_check) = first_item_in_list
            response = servicecatalog.describe_copy_product_status(CopyProductToken=copy_product_token_to_check)
            copy_product_status = response.get('CopyProductStatus')
            if copy_product_status == 'SUCCEEDED':
                if products_requiring_adding_to_portfolio.get(product_name):
                    products_requiring_adding_to_portfolio[product_name] = response.get('TargetProductId')
                copy_product_tokens.remove(first_item_in_list)
            elif copy_product_status == 'FAILED':
                raise Exception(f'Failed to copy product {copy_product_status}')
            elif copy_product_status == 'IN_PROGRESS':
                time.sleep(1)
            else:
                raise Exception(f'Not handled copy product status {response}')
    self.info('Finished waiting for copy products')
    for (product_name, product_id) in products_requiring_adding_to_portfolio.items():
        servicecatalog.associate_product_with_portfolio(ProductId=product_id, PortfolioId=spoke_portfolio_id)
    self.info('Finished associating products')
    throttle = 0
    for (product_id, product_details) in versions_requiring_updates.items():
        for (version_id, version_details) in product_details.items():
            servicecatalog.update_provisioning_artifact(ProductId=product_id, ProvisioningArtifactId=version_id, **version_details)
            throttle += 1
            if throttle == 4:
                time.sleep(1.1)
                throttle = 0
    self.info('Finished updating versions that were copied')
    products_to_check = list(products_requiring_adding_to_portfolio.values())
    n_products_to_check = len(products_to_check)
    products_found = 0
    while products_found < n_products_to_check:
        products_ids = list()
        paginator = servicecatalog.get_paginator('search_products_as_admin')
        for page in paginator.paginate(PortfolioId=spoke_portfolio_id):
            for pvd in page.get('ProductViewDetails', []):
                products_ids.append(pvd.get('ProductViewSummary').get('ProductId'))
        products_found = 0
        for product_to_check in products_to_check:
            if product_to_check in products_ids:
                products_found += 1
    self.info('Finished waiting for association of products to portfolio')
    self.write_empty_output()

def render_plugins_configuration(self, user_params_json):
    user_params = load_user_params_from_json(user_params_json)
    return PluginsConfiguration(user_params, different_config=True).render()

def _present_prompt_and_evaluate_user_input(self, include_chevron=True):
    self._load_prompt_string()
    self._current_prompt_is_done = False
    while not self._current_prompt_is_done:
        prompt_string = self._prompt_strings[-1]
        prompt_string = self._indent_and_number_prompt_string(prompt_string)
        default_value = str(self._current_prompt.default_value)
        include_chevron = self._current_prompt.include_chevron
        user_input = self._io_manager.handle_user_input(prompt_string, default_value=default_value, include_chevron=include_chevron, include_newline=self.include_newlines, prompt_character=self.prompt_character, capitalize_prompt=self.capitalize_prompts)
        if user_input is None:
            self._prompt_index += 1
            break
        directive = self._io_manager._handle_io_manager_directive(user_input)
        if self._should_backtrack():
            self._current_prompt_is_done = True
            self._all_prompts_are_done = True
        elif directive is None:
            continue
        elif directive == 'help':
            self._display_help()
        elif directive == 'previous':
            self._move_to_previous_prompt()
            break
        elif directive == 'skip':
            break
        elif isinstance(directive, str):
            self._evaluate_user_input(directive)
        else:
            self._io_manager.print_not_yet_implemented()

def register_length(self) -> int | None:
    for key in self._data:
        if key == '':
            continue
        return self[key].shape[0]
    return None

def _retrieve(self, query, format):
    if self.http_method == 'POST':
        request_method = 'POST'
    elif self.http_method == 'GET':
        request_method = 'GET'
    elif 'sld_body' in self.request_template.params:
        request_method = 'POST'
    else:
        request_method = 'GET'
    if request_method == 'POST':
        (url, data) = self._query_data(query, format)
    else:
        url = self._query_url(query, format)
        data = None
    if self.lock:
        with self.lock():
            resp = self.http_client.open(url, data=data)
    else:
        resp = self.http_client.open(url, data=data)
    self._check_resp(resp)
    return resp

def GetHostname(self, event, default_hostname=u'-'):
    hostname = getattr(event, u'hostname', None)
    if hostname:
        return hostname
    session_identifier = getattr(event, u'session_identifier', None)
    if session_identifier is None:
        return default_hostname
    hostname = self._knowledge_base.GetHostname(session_identifier=session_identifier)
    return hostname or default_hostname

def __get__(self, instance, owner):
    self._assert_have_field_name()
    if instance is None:
        return self
    if self.field_name not in instance.__dict__:
        if isinstance(self.default, types.FunctionType):
            default = self.default()
        else:
            default = self.default
        instance.__dict__[self.field_name] = default
    value = instance.__dict__[self.field_name]
    if self.required and value is None:
        raise TraitAttributeError('required attribute referenced before assignment. Use a default or assign a value before reading it', attr=self)
    return value

def iterCoordinates(self, micrograph=None):
    if micrograph is None:
        micId = None
    elif isinstance(micrograph, int):
        micId = micrograph
    elif isinstance(micrograph, Micrograph):
        micId = micrograph.getObjId()
    else:
        raise Exception('Invalid input micrograph of type %s' % type(micrograph))
    return (coord for coord in self if micId is None or coord.getMicId() == micId)

def save_run_results(cls, samples, key, run_results, overwrite=True, cache=True):
    if key is None:
        return
    dataset = samples._root_dataset
    run_docs = getattr(dataset._doc, cls._runs_field())
    run_doc = run_docs[key]
    if run_doc.results:
        if overwrite:
            run_doc.results.delete()
        else:
            raise ValueError("%s with key '%s' already has results" % (cls._run_str().capitalize(), key))
    if run_results is None:
        run_doc.results = None
    else:
        results_str = json_util.dumps(run_results)
        results_bytes = results_str.encode()
        run_doc.results.put(results_bytes, content_type='application/json')
    if cache:
        results_cache = getattr(dataset, cls._results_cache_field())
        results_cache[key] = run_results
    dataset._doc.save()

def visit_Module(self, node) -> str:
    docstring = getattr(node, 'docstring_comment', None)
    buf = [self.comment(docstring.value)] if docstring is not None else []
    filename = getattr(node, '__file__', None)
    self._reset()
    if filename is not None:
        self._module = Path(filename).stem
    body_dict: Dict[ast.AST, str] = OrderedDict()
    for b in node.body:
        if not isinstance(b, ast.FunctionDef):
            body_dict[b] = self.visit(b)
    for b in node.body:
        if isinstance(b, ast.FunctionDef):
            body_dict[b] = self.visit(b)
    buf += [body_dict[b] for b in node.body]
    return '\n'.join(buf)

def _check_error(self, value):
    if value != CKR_OK:
        if value in ERROR_CODES:
            raise P11CryptoPluginException(u._('HSM returned response code: {hex_value} {code}').format(hex_value=hex(value), code=ERROR_CODES[value]))
        else:
            raise P11CryptoPluginException(u._('HSM returned an unknown response code: {hex_value}').format(hex_value=hex(value)))

def setitem_from_path(self, path, value, trans=None):
    (path, item) = (path[:-1], path[-1])
    struct = self.struct
    for p in range(len(path)):
        part = path[p]
        if part.startswith('['):
            struct = struct[eval(part[1:-1])]
        else:
            struct = struct[part]
        if struct is None:
            return
    if isinstance(struct, (list, tuple)):
        pos = int(item)
        if pos < len(struct):
            struct[pos] = value
    elif isinstance(struct, dict):
        struct[item] = value
    elif hasattr(struct, item):
        setattr(struct, item, value)
    else:
        return
    self.update_db(trans)

