async def encrypt(self, room_id: RoomID, event_type: EventType, content: Union[Serializable, JSON]) -> Tuple[EventType, EncryptedMegolmEventContent]:
    try:
        encrypted = await self.crypto.encrypt_megolm_event(room_id, event_type, content)
    except EncryptionError:
        self.log.debug('Got EncryptionError, sharing group session and trying again')
        if await self._share_session_lock(room_id):
            try:
                users = UserProfile.all_in_room(room_id, self._id_prefix, self._id_suffix, self.bot_mxid)
                await self.crypto.share_group_session(room_id, [profile.user_id for profile in users])
            finally:
                self._share_session_events.pop(room_id).set()
        else:
            await self.crypto.wait_group_session(room_id)
        encrypted = await self.crypto.encrypt_megolm_event(room_id, event_type, content)
    return (EventType.ROOM_ENCRYPTED, encrypted)

