def setJobAttribute(self, jobID, attrName, attrValue, update=False, myDate=None):
    ret = self._escapeString(jobID)
    if not ret['OK']:
        return ret
    jobID = ret['Value']
    ret = self._escapeString(attrValue)
    if not ret['OK']:
        return ret
    value = ret['Value']
    valid_attr_names = ['status', 'priority', 'owner']
    if attrName not in valid_attr_names:
        return S_ERROR('Invalid attribute name: %s' % attrName)
    if update:
        cmd = 'UPDATE Jobs SET %s=%s,LastUpdateTime=UTC_TIMESTAMP() WHERE JobID=%s' % (attrName, value, jobID)
    else:
        cmd = 'UPDATE Jobs SET %s=%s WHERE JobID=%s' % (attrName, value, jobID)
    if myDate:
        cmd += ' AND LastUpdateTime < %s' % myDate
    res = self._update(cmd)
    if res['OK']:
        return res
    else:
        return S_ERROR('JobDB.setAttribute: failed to set attribute')

def create_segmentation_from_prediction(predicted_array_or_file: np.ndarray, dataset_json_dict_or_file: dict) -> np.ndarray:
    use_regions = any([isinstance(i, tuple) and len(i) > 1 for i in dataset_json_dict_or_file['labels'].values()])
    if use_regions:
        regions_class_order = dataset_json_dict_or_file['regions_class_order']
        segmentation = np.zeros(predicted_array_or_file.shape[1:], dtype=np.uint8)
        for (i, c) in enumerate(regions_class_order):
            segmentation[predicted_array_or_file[i] > 0.5] = c
    else:
        segmentation = predicted_array_or_file.argmax(0)
    return segmentation

def resample_and_save(predicted: Union[str, np.ndarray], target_shape: List[int], output_file: str, plans_dict_or_file: Union[dict, str], configuration_name: str, properties_dict: dict, dataset_json_dict_or_file: Union[dict, str], next_configuration: str) -> None:
    if isinstance(predicted, str):
        assert isfile(predicted), 'If isinstance(segmentation_softmax, str) then isfile(segmentation_softmax) must be True'
        del_file = deepcopy(predicted)
        predicted = np.load(predicted)
        os.remove(del_file)
    if isinstance(plans_dict_or_file, str):
        plans_dict_or_file = load_json(plans_dict_or_file)
    if isinstance(dataset_json_dict_or_file, str):
        dataset_json_dict_or_file = load_json(dataset_json_dict_or_file)
    resampling_fn = recursive_find_resampling_fn_by_name(plans_dict_or_file['configurations'][configuration_name]['resampling_fn_softmax'])
    current_spacing = plans_dict_or_file['configurations'][configuration_name]['spacing'] if len(plans_dict_or_file['configurations'][configuration_name]['spacing']) == len(properties_dict['shape_after_cropping_and_before_resampling']) else [properties_dict['spacing'][0], *plans_dict_or_file['configurations'][configuration_name]['spacing']]
    target_spacing = plans_dict_or_file['configurations'][next_configuration]['spacing'] if len(plans_dict_or_file['configurations'][next_configuration]['spacing']) == len(properties_dict['shape_after_cropping_and_before_resampling']) else [properties_dict['spacing'][0], *plans_dict_or_file['configurations'][next_configuration]['spacing']]
    predicted_array_or_file = resampling_fn(predicted, target_shape, current_spacing, target_spacing, **plans_dict_or_file['configurations'][configuration_name]['resampling_fn_softmax_kwargs'])
    segmentation = create_segmentation_from_prediction(predicted_array_or_file, dataset_json_dict_or_file)
    np.savez_compressed(output_file, seg=segmentation.astype(np.uint8))

def init_new_world(self):
	loggers_to_silence = { 'world.production' : None }
	for logger_name in loggers_to_silence:
