    assert ret_coords is not None, 'Return coords are none. No players loaded?'
    return ret_coords

def aistudio_download(repo_id: str, filename: str=None, cache_dir: Optional[str]=None, subfolder: Optional[str]='', revision: Optional[str]=None, **kwargs):
    if revision is None:
        revision = 'master'
    filename = _add_subfolder(filename, subfolder)
    download_kwargs = {}
    if revision is not None:
        download_kwargs['revision'] = revision
    if cache_dir is not None:
        download_kwargs['local_dir'] = cache_dir
    res = download(repo_id=repo_id, filename=filename, **download_kwargs)
    if 'path' in res:
        return res['path']
    elif res['error_code'] == 10001:
        raise ValueError('Illegal argument error')
    elif res['error_code'] == 10002:
        raise UnauthorizedError('Unauthorized Access. Please ensure that you have provided the AIStudio Access Token and you have access to the requested asset')
    elif res['error_code'] == 12001:
        raise EntryNotFoundError(f"Cannot find the requested file '{filename}' in repo '{repo_id}'")
    else:
        raise Exception(f'Unknown error: {res}')

def set_tag_end_ms(tag, end_ms):
    with db_transaction():
        updated = Tag.update(lifetime_end_ms=end_ms).where(Tag.id == tag).where(Tag.lifetime_end_ms == tag.lifetime_end_ms).execute()
        if updated != 1:
            return (None, False)
        return (tag.lifetime_end_ms, True)

def registeropt(self, name, valuetype, where, default):
    if not any((opt[0] == name for opt in self.opts)):
