def announce(self, negotiated, nlris=None, mps=None):
    asn4 = negotiated.asn4
    local_as = negotiated.local_as
    peer_as = negotiated.peer_as
    msg_size = negotiated.msg_size
    attr = self.attributes.pack(asn4, local_as, peer_as)
    if nlris is None and mps is None:
        packed_nlri = []
        packed_mp = []
        for nlri in self.nlris:
            (afi, safi) = (nlri.afi, nlri.safi)
            addpath = negotiated.addpath.send(afi, safi)
            if nlri.family() in negotiated.families:
                if afi == AFI.ipv4 and safi in [SAFI.unicast, SAFI.multicast] and (nlri.nexthop == self.attributes.get(AID.NEXT_HOP, None)):
                    packed_nlri.append(nlri)
                else:
                    packed_mp.append(nlri)
        else:
            packed_nlri = nlris
            packed_mp = mps
    if not packed_nlri and (not packed_mp):
        return ''
    return self.make_message(msg_size, attr, MPRNLRI(packed_mp).pack(addpath), ''.join((nlri.pack(addpath) for nlri in packed_nlri)))

def _call_series(self, series):
    level = getattr(self, 'level', None)
    axis = getattr(self, 'axis', None)
    skipna = getattr(self, 'skipna', None)
    numeric_only = getattr(self, 'numeric_only', None)
    bool_only = getattr(self, 'bool_only', None)
    if axis == 'index':
        axis = 0
    self._axis = axis
    empty_series = build_series(series)
    func_name = getattr(self, '_func_name')
    if func_name == 'count':
        reduced_series = empty_series.count(level=level)
    elif func_name == 'nunique':
        reduced_series = empty_series.nunique()
    elif func_name in ('all', 'any'):
        reduced_series = getattr(empty_series, func_name)(axis=axis, level=level, bool_only=bool_only)
    elif func_name == 'size':
        reduced_series = empty_series.size
    elif func_name == 'custom_reduction':
        reduced_series = getattr(self, 'custom_reduction').__call_agg__(empty_series)
    elif func_name == 'str_concat':
        reduced_series = pd.Series([empty_series.str.cat(**getattr(self, 'get_reduction_args')())])
    else:
        reduced_series = getattr(empty_series, func_name)(axis=axis, level=level, skipna=skipna, numeric_only=numeric_only)
    return self.new_scalar([series], dtype=np.array(reduced_series).dtype)

