        providers = []
    return map(lambda x: x.key, providers)

def providers(self):
    feature_flag_enabled = False
    all_providers = list(integrations.all())
    if feature_flag_enabled:
        providers = filter(lambda x: x.has_stacktrace_linking, all_providers)
    else:
        providers = all_providers
    return map(lambda x: x.key, providers)

