def sync_remote_repositories(user_id):
    user = User.objects.filter(pk=user_id).first()
    if not user:
        return
    failed_services = set()
    for service_cls in registry:
        for service in service_cls.for_user(user):
            try:
                service.sync()
            except SyncServiceError:
                failed_services.add(service.provider_name)
    if failed_services:
        msg = _('Our access to your following accounts was revoked: {providers}. Please, reconnect them from your social account connections.')
        raise Exception(msg.format(providers=', '.join(failed_services)))

