def convex_conj(self):
    if self.exponent == np.inf:
        return L1Norm(self.domain)
    elif self.exponent == 2:
        return L2Norm(self.domain)
    else:
        return LpNorm(self.domain, self.exponent)

def iconName(self):
    (r, g, b, a) = (c / 255 for c in wx.SystemSettings.GetColour(wx.SYS_COLOUR_WINDOW))
    l = (max(r, g, b) + min(r, g, b)) / 2
    suffix = '_black' if l > 0.3 else '_white'
    return '{}{}'.format(self._iconNamePrefix, suffix)

def _publish(self, context: SnsPublishContext, subscriber: SnsSubscription):
    try:
        region = extract_region_from_arn(subscriber['Endpoint'])
        lambda_client = connect_to(region_name=region).awslambda.request_metadata(source_arn=subscriber['TopicArn'], service_principal='sns')
        event = self.prepare_message(context.message, subscriber)
        inv_result = lambda_client.invoke(FunctionName=subscriber['Endpoint'], Payload=to_bytes(event), InvocationType=InvocationType.Event)
        status_code = inv_result.get('StatusCode')
        payload = inv_result.get('Payload')
        if payload:
            request_id = inv_result.get('ResponseMetadata', {}).get('RequestId')
            if not request_id:
                request_id = long_uid()
            delivery = {'statusCode': status_code, 'providerResponse': json.dumps({'lambdaRequestId': request_id})}
            store_delivery_log(context.message, subscriber, success=True, delivery=delivery)
    except Exception as exc:
        LOG.info('Unable to run Lambda function on SNS message: %s %s', exc, traceback.format_exc())
        store_delivery_log(context.message, subscriber, success=False)
        message_body = create_sns_message_body(message_context=context.message, subscriber=subscriber)
        sns_error_to_dead_letter_queue(subscriber, message_body, str(exc))

def __eq__(self, other: object) -> bool:
    if not isinstance(other, Matrix):
        raise TypeError('Matrix class required.')
    if self.shape != other.shape:
        raise TypeError('Matrices have different shapes.')
    return np.all(np.isclose(self.matrix, other.matrix, atol=self.abs_tol))

def _get_data(self):
    try:
        data = self.connection.recv(4)
        if not data:
            time.sleep(1e-06)
            return self._get_data()
        length = int.from_bytes(data, 'little')
        strings = []
        while len(''.join(strings)) != length:
            strings.append(self.connection.recv(length).decode())
        return ''.join(strings)
    except socket.timeout as e:
        print('env timed out', e)
    return None

def infer_type(self, expr: E.Apply) -> T.Base:
    if len(expr.arguments) != 1:
        raise Error.WrongArity(expr, 1)
    if not isinstance(expr.arguments[0].type, T.Array) or (expr.arguments[0]._check_quant and expr.arguments[0].type.optional):
        raise Error.StaticTypeMismatch(expr.arguments[0], T.Array(T.Any()), expr.arguments[0].type)
    if isinstance(expr.arguments[0].type.item_type, T.Any):
        raise Error.IndeterminateType(expr.arguments[0])
    ty = expr.arguments[0].type.item_type
    assert isinstance(ty, T.Base)
    return ty.copy(optional=False)

def _purchase_service_create(self, quantity=False):
    PurchaseOrder = self.env['purchase.order']
    supplier_po_map = {}
    sale_line_purchase_map = {}
    for line in self:
        line = line.with_company(line.company_id)
        supplierinfo = line._select_seller()
        if not supplierinfo:
            raise UserError(_('There is no vendor associated to the product %s. Please define a vendor for this product.') % (line.product_id.display_name,))
        partner_supplier = supplierinfo.name
        purchase_order = supplier_po_map.get(partner_supplier.id)
        if not purchase_order:
            purchase_order = PurchaseOrder.search([('partner_id', '=', partner_supplier.id), ('state', '=', 'draft'), ('company_id', '=', line.company_id.id)], limit=1)
        if not purchase_order:
            values = line._purchase_service_prepare_order_values(supplierinfo)
            purchase_order = PurchaseOrder.create(values)
        else:
            so_name = line.order_id.name
            origins = []
            if purchase_order.origin:
                origins = purchase_order.origin.split(', ') + origins
            if so_name not in origins:
                origins += [so_name]
                purchase_order.write({'origin': ', '.join(origins)})
        supplier_po_map[partner_supplier.id] = purchase_order
        values = line._purchase_service_prepare_line_values(purchase_order, quantity=quantity)
        purchase_line = line.env['purchase.order.line'].create(values)
        sale_line_purchase_map.setdefault(line, line.env['purchase.order.line'])
        sale_line_purchase_map[line] |= purchase_line
    return sale_line_purchase_map

def __int__(self) -> int:
    resolved = self.resolved()
    if resolved is None:
        raise TypeError(f'cannot convert unset {repr(self)} to int')
    return resolved

