def _format_class_body(statements: List, context: Context) -> (List[str], int):
    formatted_lines = []
    previously_processed_line_number = context.previously_processed_line_number
    for statement in statements:
        formatted_lines += _reconstruct_blank_lines_in_range(previously_processed_line_number, statement.line, context.comments, ' ' * context.indent)
        previously_processed_line_number = statement.line
        if statement.data == 'tool_stmt':
            formatted_lines.append('{}tool'.format(' ' * context.indent))
        elif statement.data == 'class_def':
            name = statement.children[0].value
            formatted_lines.append('{}class {}:'.format(' ' * context.indent, name))
            (class_lines, last_processed_line) = _format_class_body(statement.children[1:], Context(indent=context.indent + 4, previously_processed_line_number=previously_processed_line_number, comments=context.comments))
            formatted_lines += class_lines
            previously_processed_line_number = last_processed_line
        if context.comments[statement.line] is not None:
            formatted_lines[-1] = '{}  {}'.format(formatted_lines[-1], context.comments[statement.line])
    formatted_lines += _reconstruct_blank_lines_in_range(previously_processed_line_number, max(context.comments.keys()) + 1 if context.comments else previously_processed_line_number, context.comments, ' ' * context.indent)
    return (formatted_lines, previously_processed_line_number)

def emit_c_api(self, ctx: CompileCtx) -> None:

    def render(template_name: str) -> str:
