def _sqlalchemy_type(self, col):
    dtype = self.dtype or {}
    if col.name in dtype:
        return self.dtype[col.name]
    col_type = self._get_notnull_col_dtype(col)
    from sqlalchemy.types import BigInteger, Float, Text, Boolean, DateTime, Date, Time, Integer
    if col_type == 'datetime64' or col_type == 'datetime':
        try:
            tz = col.tzinfo
            return DateTime(timezone=True)
        except:
            return DateTime
    if col_type == 'timedelta64':
        warnings.warn("the 'timedelta' type is not supported, and will be written as integer values (ns frequency) to the database.", UserWarning)
        return BigInteger
    elif col_type == 'floating':
        return Float
    elif col_type == 'integer':
        if col.dtype == np.int32:
            return Integer
        else:
            return BigInteger
    elif col_type == 'boolean':
        return Boolean
    elif col_type == 'date':
        return Date
    elif col_type == 'time':
        return Time
    elif col_type == 'complex':
        raise ValueError('Complex datatypes not supported')
    return Text

async def _request_wrapper(self, url: str, method: str, request_data: Optional[RequestData]=None, read_timeout: ODVInput[float]=DEFAULT_NONE, write_timeout: ODVInput[float]=DEFAULT_NONE, connect_timeout: ODVInput[float]=DEFAULT_NONE, pool_timeout: ODVInput[float]=DEFAULT_NONE) -> bytes:
    try:
        (code, payload) = await self.do_request(url=url, method=method, request_data=request_data, read_timeout=read_timeout, write_timeout=write_timeout, connect_timeout=connect_timeout, pool_timeout=pool_timeout)
    except TelegramError as exc:
        raise exc
    except Exception as exc:
        raise NetworkError(f'Unknown error in HTTP implementation: {exc!r}') from exc
    if HTTPStatus.OK <= code <= 299:
        return payload
    response_data = self.parse_json_payload(payload)
    description = response_data.get('description')
    message = description if description else 'Unknown HTTPError'
    parameters = response_data.get('parameters')
    if parameters:
        migrate_to_chat_id = parameters.get('migrate_to_chat_id')
        if migrate_to_chat_id:
            raise ChatMigrated(migrate_to_chat_id)
        retry_after = parameters.get('retry_after')
        if retry_after:
            raise RetryAfter(retry_after)
        message += f'\nThe server response contained unknown parameters: {parameters}'
    if code == HTTPStatus.FORBIDDEN:
        raise Forbidden(message)
    if code in (HTTPStatus.NOT_FOUND, HTTPStatus.UNAUTHORIZED):
        raise InvalidToken(message)
    if code == HTTPStatus.BAD_REQUEST:
        raise BadRequest(message)
    if code == HTTPStatus.CONFLICT:
        raise Conflict(message)
    if code == HTTPStatus.BAD_GATEWAY:
        raise NetworkError(description or 'Bad Gateway')
    raise NetworkError(f'{message} ({code})')

