def forgot_password_post():
    form = ForgotPasswordForm(request.form, prefix='forgot_password')
    if form.validate():
        email = form.email.data
        status_message = 'If there is an OSF account associated with {0}, an email with instructions on how to reset the OSF password has been sent to {0}. If you do not receive an email and believe you should have, please contact OSF Support. '.format(email)
        user_obj = get_user(email=email)
        if user_obj:
            if not throttle_period_expired(user_obj.email_last_sent, settings.SEND_EMAIL_THROTTLE):
                status_message = 'You have recently requested to change your password. Please wait a few minutes before trying again.'
                status.push_status_message(status_message, 'error')
            else:
                user_obj.verification_key_v2 = generate_verification_key(verification_type='password')
                user_obj.email_last_sent = timezone.now()
                reset_link = urljoin(settings.DOMAIN, web_url_for('reset_password_get', uid=user_obj._id, token=user_obj.verification_key_v2['token']))
                notificaton_type.instance.emit(user=user_obj, event_context={'reset_link': reset_link})
                status.push_status_message(status_message, 'success')
        else:
            status.push_status_message(status_message, 'success')
    forms.push_errors_to_status(form.errors)
    return auth_login(forgot_password_form=form)

import jsonschema
from jsonschema import validate

class YourClass:

    def frsw_allocate_udp_port(self, request):
        if request is None:
            self.send_param_error()
            return
        schema = {'type': 'object', 'properties': {'id': {'type': 'string'}, 'port_id': {'type': 'string'}}, 'required': ['id', 'port_id']}
        try:
            validate(instance=request, schema=schema)
        except jsonschema.exceptions.ValidationError as e:
            self.send_custom_error(f'Invalid request: {e.message}')
            return
        log.debug('received request {}'.format(request))
        frsw_id = request['id']
        if frsw_id not in self._frame_relay_switches:
            self.send_custom_error("Frame relay switch id {} doesn't exist".format(frsw_id))
            return
        frsw = self._frame_relay_switches[frsw_id]
        try:
            response = self.allocate_udp_port(frsw)
        except DynamipsError as e:
            self.send_custom_error(str(e))
            return
        response['port_id'] = request['port_id']
        self.send_response(response)

def maintain_process_mapping(self):
    import time, subprocess
    while self.device.is_connected:
        ps_out = subprocess.check_output(['adb', 'shell', 'ps'])
        ps_out = ps_out.decode('utf-8')
        self.pid2uid = {}
        self.pid2name = {}
        lines = ps_out.strip().split('\n')
        for line in lines[1:]:
            parts = line.split()
            if len(parts) < 9:
                continue
            uid = parts[0]
            pid = parts[1]
            name = parts[-1]
            self.pid2uid[pid] = uid
            self.pid2name[pid] = name
        time.sleep(1)

def zeros_like(a, dtype=None, order='K'):
    if dtype is None:
        dtype = a.dtype
    out = cupy.empty_like(a, dtype=dtype, order=order)
    out.fill(0)
    return out

def _call(self, method, *args, **kwargs):
    tid = self._tid.next()
    msg = {'method': method, 'params': list(args)}
    is_notify = '_notify' in kwargs
    if not is_notify:
        msg['id'] = tid
    msg = json.dumps(msg)
    for timeout in self._service.iter_rpc_retry_timeout():
        services = self._service.resolve_service(self._service_name)
        if not services:
            raise RPCError('Service not found')
        for svc in services:
            client = tornado.httpclient.AsyncHTTPClient()
            try:
                response = (yield client.fetch('http://%s/api/%s/' % (svc, self._api), method='POST', body=msg))
            except tornado.httpclient.HTTPError as why:
                if why.code != 499:
                    raise RPCError('RPC Call Failed: %s', why)
                else:
                    self._service.logger.info('Service is not available at %s. Retrying', svc)
                    continue
            except Exception as why:
                if 'Connection refused' in str(why):
                    self._service.logger.error('Connection refused when trying to reach %s. Retrying...', svc)
                    continue
                raise RPCError('RPC Call Failed: %s' % why)
            if not is_notify:
                result = json.loads(response.body)
                if result.get('error'):
                    raise RPCError('RPC Call Failed: %s' % result['error'])
                else:
                    raise tornado.gen.Return(result['result'])
        self._service.logger.info('All services are not available. Waiting %s seconds')
        yield tornado.gen.sleep(timeout)

def _passthru(http_methods, method=None, async_call=True, driver_passthru=False, description=None, attach=False, require_exclusive_lock=True):

    def handle_passthru(func):
        api_method = method
        if api_method is None:
            api_method = func.__name__
        supported_ = [i.upper() for i in http_methods]
        description_ = description or ''
        metadata = VendorMetadata(api_method, {'http_methods': supported_, 'async': async_call, 'description': description_, 'attach': attach})
        if driver_passthru:
            func._driver_metadata = metadata
        else:
            metadata[1]['require_exclusive_lock'] = require_exclusive_lock
            func._vendor_metadata = metadata
        passthru_logmessage = 'vendor_passthru failed with method %s'

        @six.wraps(func)
        def passthru_handler(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except exception.IronicException as e:
                with excutils.save_and_reraise_exception():
                    LOG.exception(passthru_logmessage, api_method)
            except Exception as e:
                LOG.exception(passthru_logmessage, api_method)
                raise exception.VendorPassthruException(message=e)
        return passthru_handler
    return handle_passthru

