import asyncio
import logging
from typing import TYPE_CHECKING, Any
from packaging.utils import canonicalize_name
from .errors import ConnectionTimeout, PackageNotFound, StaleMetadata
from .master import StalePage
if TYPE_CHECKING:
    from .filter import Filter
    from .master import Master
logger = logging.getLogger(__name__)

class Package:

    def __init__(self, name: str, serial: int=0) -> None:
        self.name: str = canonicalize_name(name)
        self.raw_name = name
        self.serial = serial
        self._metadata: dict | None = None

    @property
    def metadata(self) -> dict[str, Any]:
        assert self._metadata is not None, 'Must fetch metadata before accessing it'
        return self._metadata

    @property
    def info(self) -> Any:
        return self.metadata['info']

    @property
    def last_serial(self) -> int:
        return int(self.metadata['last_serial'])

    @property
    def releases(self) -> Any:
        return self.metadata['releases']

    @property
    def release_files(self) -> list:
        release_files: list[dict] = []
        for release in self.releases.values():
            release_files.extend(release)
        return release_files

    async def update_metadata(self, master: 'Master', attempts: int=3) -> None:
        tries = 0
        sleep_on_stale = 1
        while tries < attempts:
            try:
                logger.info(f'Fetching metadata for package: {self.name} (serial {self.serial})')
                self._metadata = await master.get_package_metadata(self.name, serial=self.serial)
                return
            except PackageNotFound as e:
                logger.info(str(e))
                raise
            except (StalePage, TimeoutError) as e:
                (error_name, error_class) = ('Stale serial', StaleMetadata) if isinstance(e, StalePage) else ('Timeout error', ConnectionTimeout)
                tries += 1
                logger.error(f'{error_name} for package {self.name} - Attempt {tries}')
                if tries < attempts:
                    logger.debug(f'Sleeping {sleep_on_stale}s to give CDN a chance')
                    await asyncio.sleep(sleep_on_stale)
                    sleep_on_stale *= 2
                    continue
                logger.error(f'{error_name} for {self.name} ({self.serial}) ' + 'not updating. Giving up.')
                raise error_class(package_name=self.name, attempts=attempts)

    async def sync_release_files(self):
        release_files = self.release_files
        downloaded_files = set()
        deferred_exception = None

        async def download_file_async(release_file):
            try:
                downloaded_file = await self.download_file(release_file['url'], release_file['digests']['sha256'])
                if downloaded_file:
                    downloaded_files.add(str(downloaded_file.relative_to(self.mirror.homedir)))
            except Exception as e:
                logger.exception(f"Continuing to next file after error downloading: {release_file['url']}")
                nonlocal deferred_exception
                if not deferred_exception:
                    deferred_exception = e
        await asyncio.gather(*(download_file_async(release_file) for release_file in release_files))
        if deferred_exception:
            raise deferred_exception
        self.mirror.altered_packages[self.name] = downloaded_files

def _make_elementwise_binary_reference(prim: Callable, *, type_promotion_kind, aten_op=infer_aten_op, has_out=True, supports_lhs_python_scalar=True, supports_rhs_python_scalar=True) -> Callable:

    @elementwise_type_promotion_wrapper(type_promoting_args=('a', 'b'), type_promotion_kind=type_promotion_kind)
    def _ref(a: Union[Tensor, NumberType], b: Union[Tensor, NumberType]) -> Tensor:
        if not supports_lhs_python_scalar and isinstance(a, Number):
            raise ValueError('Received a lhs Python scalar to an elementwise binary operation that does not accept lhs scalars!')
        if not supports_rhs_python_scalar and isinstance(b, Number):
            raise ValueError('Received a rhs Python scalar to an elementwise binary operation that does not accept rhs scalars!')
        if isinstance(a, Number) and isinstance(b, Number) and (prim.__name__ == 'add'):
            return prim(a, b)
        (a, b) = _maybe_broadcast(a, b)
        return prim(a, b)
    if has_out:
        _ref = out_wrapper()(_ref)
    if aten_op is infer_aten_op:
        aten_op = getattr(torch.ops.aten, prim.__name__.split('.')[0])
    if aten_op is not None:
        register_decomposition(aten_op)(_ref)
    return _ref

