def on_builtin_offsetof(self, typ, member_name, location):
    if not isinstance(typ, types.StructOrUnionType):
        self.error('Can only apply offsetof on structs and unions', location)
    if not self.context.has_field(typ, member_name):
        self.error(f'Cannot find member {member_name}', location)
    field = self.context.get_field(typ, member_name)
    if field.is_bitfield:
        self.error(f'Attempt to take address of bit-field "{member_name}"', location)
    return expressions.BuiltInOffsetOf(typ, member_name, self.int_type, location)

def set_parameters(self, config={}):
    self.tomography_scheme = config.get('Tomography scheme')
    if self.tomography_scheme == 'Single qubit':
        self.singleQBtomoID = int(config.get('Qubit for tomography'))
        self.tomography_index = config.get('Tomography pulse index 1-QB')
    elif self.tomography_scheme in ['Two qubit (9 pulse set)', 'Two qubit (30 pulse set)', 'Two qubit (36 pulse set)']:
        self.twoQBtomoID1 = int(config.get('Qubit 1 # tomography'))
        self.twoQBtomoID2 = int(config.get('Qubit 2 # tomography'))
        pulseCall = 'Tomography pulse index 2-QB' + self.tomography_scheme[9:]
        self.tomography_index = config.get(pulseCall)

