        supported_content = []
    else:
        supported_content = content_binding_entities_to_content_bindings(collection.supported_content, version=version)
    if version == 11:
        inbox_instances = []
        for inbox in service.get_receiving_inbox_services(collection):
            inbox_instances.extend(inbox_to_receiving_inbox_instance(inbox))
        return tm11.CollectionInformation(collection_name=collection.name, collection_description=collection.description, supported_contents=supported_content, available=collection.available, push_methods=push_methods, polling_service_instances=polling_instances, subscription_methods=subscription_methods, collection_volume=int(service.get_volume(collection)), collection_type=collection.type, receiving_inbox_services=inbox_instances)
    else:
        return tm10.FeedInformation(feed_name=collection.name, feed_description=collection.description, supported_contents=supported_content, available=collection.available, push_methods=push_methods, polling_service_instances=polling_instances, subscription_methods=subscription_methods)
    raise ValueError('invalid version')

