def test_json_schema():

    @validate_call
    def foo(a: int, b: int=None):
        return f'{a}, {b}'
    assert foo(1, 2) == '1, 2'
    assert foo(1, b=2) == '1, 2'
    assert foo(1) == '1, None'
    assert TypeAdapter(foo).json_schema() == {'type': 'object', 'properties': {'a': {'title': 'A', 'type': 'integer'}, 'b': {'default': None, 'title': 'B', 'type': 'integer'}}, 'required': ['a'], 'additionalProperties': False}

    @validate_call
    def foo(a: int, /, b: int):
        return f'{a}, {b}'
    assert foo(1, 2) == '1, 2'
    assert TypeAdapter(foo).json_schema() == {'maxItems': 2, 'minItems': 2, 'prefixItems': [{'title': 'A', 'type': 'integer'}, {'title': 'B', 'type': 'integer'}], 'type': 'array'}

    @validate_call
    def foo(a: int, /, *, b: int, c: int):
        return f'{a}, {b}, {c}'
    assert foo(1, b=2, c=3) == '1, 2, 3'
    with pytest.raises(PydanticInvalidForJsonSchema, match='Unable to generate JSON schema for arguments validator with positional-only and keyword-only arguments'):
        TypeAdapter(foo).json_schema()

    @validate_call
    def foo(*numbers: int) -> int:
        return sum(numbers)
    assert foo(1, 2, 3) == 6
    assert TypeAdapter(foo).json_schema() == {'items': {'type': 'integer'}, 'prefixItems': [], 'type': 'array'}

    @validate_call
    def foo(**scores: int) -> str:
        return ', '.join((f'{k}={v}' for (k, v) in sorted(scores.items())))
    assert foo(a=1, b=2) == 'a=1, b=2'
    assert TypeAdapter(foo).json_schema() == {'additionalProperties': {'type': 'integer'}, 'properties': {}, 'type': 'object'}

    @validate_call
    def foo(a: Annotated[int, Field(..., alias='A')]):
        return a
    assert foo(1) == 1
    assert TypeAdapter(foo).json_schema() == {'additionalProperties': False, 'properties': {'A': {'title': 'A', 'type': 'integer'}}, 'required': ['A'], 'type': 'object'}

def validate_grid_districts(self):
    msg_invalidity = []
    invalid_mv_grid_districts = []
    for grid_district in self.mv_grid_districts():
        if len(grid_district.mv_grid._graph.nodes()) == 1:
            invalid_mv_grid_districts.append(grid_district)
            msg_invalidity.append('MV Grid District {} seems to be empty and was removed'.format(grid_district))
        elif all([lvla.is_aggregated for lvla in grid_district.lv_load_areas()]):
            invalid_mv_grid_districts.append(grid_district)
            msg_invalidity.append('MV Grid District {} contains only aggregated Load Areas and was removed'.format(grid_district))
    for grid_district in invalid_mv_grid_districts:
        self._mv_grid_districts.remove(grid_district)
    logger.warning('\n'.join(msg_invalidity))
    logger.info('=====> MV Grids validated')
    return msg_invalidity

import logging

def run(self, server, varargs, kwargs=None):
    if kwargs is None:
        kwargs = {}
    message = '%s\t' % str(server)
    response = None
    try:
        response = self.routine(*varargs, **kwargs)
        self.handle_response(response, message)
    except (CommError, KeyError, ValueError) as e:
        logging.error(message + '%s: %s\n' % (e.__class__.__name__, e))
        self.all_ok = False

def Run(self, cmd_val):
    (attrs, offset) = arg_def.ParseCmdVal('unset', cmd_val)
    arg = arg_types.unset(attrs.attrs)
    for (name, spid) in zip(cmd_val.argv[offset:], cmd_val.arg_spids[offset:]):
        if arg.f:
            if name in self.funcs:
                del self.funcs[name]
        elif arg.v:
            if not self._UnsetVar(name, spid, False):
                return 1
        elif not self._UnsetVar(name, spid, True):
            return 1
    return 0

def release_pgcon(self, dbname, conn, *, discard=False):
    if not conn.is_healthy_to_go_back_to_pool():
        logger.warning("Connection to database '%s' is unhealthy and shouldn't happen.", dbname)
        discard = True
    self._pg_pool.release(dbname, conn, discard=discard)

def fromfile(cls, filename):
    fheader = path.splitext(filename)[0] + '.header'
    if path.isfile(fheader) and path.isfile(filename):
        with open(fheader, 'r', encoding='utf-8', errors='replace') as fd:
            for line in fd:
                if line.startswith('ArrayDesc('):
                    m = re.match(".*\\((\\d+(?:,\\s*\\d+)*)\\).*dtype\\(\\'(.*)\\'\\).*", line)
                    if m:
                        dims_str = m.group(1)
                        dtype = m.group(2)
                        dims = tuple((int(d.strip()) for d in dims_str.split(',')))
                        return np.fromfile(filename, dtype).reshape(dims)
            raise NicosError('no ArrayDesc line found')
    else:
        raise NicosError('file and/or corresponding .header not found')

