def _analyze(self, oFile, oLine, iLineNumber):
    if oLine.__dict__[self.sTrigger]:
        words = self._extract(oLine)
        if self.case == 'lower':
            check_function = check.is_lowercase
        else:
            check_function = check.is_uppercase
        for word in words:
            if check_function(self, word, iLineNumber) == False:
                self.words_to_fix.add(word)
            else:
                raise ValueError(f"Case mismatch for word '{word}' at line {iLineNumber}")

def _analyze(self, oFile, oLine, iLineNumber):
    if oLine.__dict__[self.sTrigger]:
        words = self._extract(oLine)
        if self.case == 'lower':
            check_function = check.is_lowercase
        else:
            check_function = check.is_uppercase
        for word in words:
            if not check_function(self, word, iLineNumber):
                self.words_to_fix.add(word)
            else:
                raise ValueError(f'Case mismatch detected for word: {word}')

def read(self):
    import warnings
    metadata_files = ('METADATA', 'PKG-INFO')
    if self.entry_point and self.entry_point.dist:
        for metadata_file in metadata_files:
            try:
                return self.entry_point.dist.get_metadata(metadata_file)
            except Exception as e:
                logging.exception(f'Error retrieving metadata for {metadata_file}: {e}')
        warnings.warn('No package metadata found for package: {}'.format(self.entry_point.module_name))

def compile_Set(expr: qlast.Base, *, ctx: context.ContextLevel) -> irast.Base:
    if expr.elements:
        if len(expr.elements) == 1:
            return dispatch.compile(expr.elements[0], ctx=ctx)
        else:
            elements = flatten_set(expr)
            bigunion = qlast.BinOp(left=elements[0], right=elements[1], op=qlast.UNION_ALL)
            for el in elements[2:]:
                bigunion = qlast.BinOp(left=bigunion, right=el, op=qlast.UNION_ALL)
            return dispatch.compile(bigunion, ctx=ctx)
    else:
        return irast.EmptySet()

def collectOutputNow(self, exe, suggest_filename=None, root_symlink=False):
    timeout_seconds = 30
    try:
        (status, shout, runtime) = sosGetCommandOutput(exe, timeout=timeout_seconds)
    except TimeoutError:
        self.soslog.log(logging.WARNING, f'command timed out: {exe}')
        (status, shout, runtime) = (-1, '', 0)
    if suggest_filename:
        outfn = self.makeCommandFilename(suggest_filename)
    else:
        outfn = self.makeCommandFilename(exe)
    if not os.path.isdir(os.path.dirname(outfn)):
        os.mkdir(os.path.dirname(outfn))
    if not (status == 127 or status == 32512 or status == -1):
        outfd = open(outfn, 'w')
        if len(shout):
            outfd.write(shout + '\n')
        outfd.close()
        if root_symlink:
            curdir = os.getcwd()
            os.chdir(self.cInfo['dstroot'])
            os.symlink(outfn[len(self.cInfo['dstroot']) + 1:], root_symlink.strip('/.'))
            os.chdir(curdir)
        outfn_strip = outfn[len(self.cInfo['cmddir']) + 1:]
    else:
        self.soslog.log(logging.VERBOSE, 'could not run command: %s' % exe)
        outfn = None
        outfn_strip = None
    self.executedCommands.append({'exe': exe, 'file': outfn_strip})
    self.cInfo['xmlreport'].add_command(cmdline=exe, exitcode=status, f_stdout=outfn_strip, runtime=runtime)
    return outfn

def full_graph(self):
    full_root_rules = set()
    full_dependency_edges = {}
    full_unfulfillable_rules = {}
    for (root_subject_type, selector_fn) in self.root_subject_selector_fns.items():
        for product in sorted(self.nodebuilder.all_produced_product_types(root_subject_type)):
            root_rule = RootRule(root_subject_type, selector_fn(product))
            (root_dependencies, rule_dependency_edges, unfulfillable_rules) = self._construct_graph(root_rule, full_dependency_edges)
            full_root_rules.update(root_dependencies)
            full_dependency_edges.update(rule_dependency_edges)
            full_unfulfillable_rules.update(unfulfillable_rules)
    rules_in_graph = set((entry.rule for entry in full_dependency_edges.keys()))
    rules_eliminated_during_construction = set((entry.rule for entry in full_unfulfillable_rules.keys()))
    declared_rules = self.nodebuilder.all_rules()
    unreachable_rules = declared_rules.difference(rules_in_graph, rules_eliminated_during_construction)
    for rule in sorted(unreachable_rules):
        full_unfulfillable_rules[UnreachableRule(rule)] = [Diagnostic(None, 'Unreachable')]
    return RuleGraph(self.root_subject_selector_fns, list(full_root_rules), full_dependency_edges, full_unfulfillable_rules)

