from django import forms

class MapObjectsForm(forms.Form):
    album_id = forms.IntegerField(required=False)
    area_id = forms.IntegerField(required=False)
    limit_by_album = forms.BooleanField(required=False)
    sw_lat = forms.FloatField(required=False)
    sw_lon = forms.FloatField(required=False)
    ne_lat = forms.FloatField(required=False)
    ne_lon = forms.FloatField(required=False)

def map_objects_by_bounding_box(request):
    form = MapObjectsForm(request.POST)
    if not form.is_valid():
        return HttpResponse(json.dumps({'error': 'Invalid input'}), content_type='application/json')
    album_id = form.cleaned_data.get('album_id')
    area_id = form.cleaned_data.get('area_id')
    limit_by_album = form.cleaned_data.get('limit_by_album', False)
    qs = Photo.objects.all()
    ungeotagged_count = 0
    geotagged_count = 0
    if album_id is not None or area_id is not None:
        (ungeotagged_count, geotagged_count) = qs.get_album_photo_count_and_total_geotag_count(album_id, area_id)
        if album_id and limit_by_album:
            album = Album.objects.get(pk=album_id)
            album_photo_ids = list(album.photos.values_list('id', flat=True))
            for sa in album.subalbums.all():
                album_photo_ids += list(sa.photos.values_list('id', flat=True))
            qs = qs.filter(id__in=album_photo_ids)
    if form.cleaned_data.get('sw_lat') and form.cleaned_data.get('sw_lon') and form.cleaned_data.get('ne_lat') and form.cleaned_data.get('ne_lon'):
        bounding_box = (form.cleaned_data['sw_lat'], form.cleaned_data['sw_lon'], form.cleaned_data['ne_lat'], form.cleaned_data['ne_lon'])
        data = qs.get_geotagged_photos_list(bounding_box)
        data = {'photos': data, 'geotagged_count': geotagged_count, 'ungeotagged_count': ungeotagged_count}
    else:
        data = {'photos': [], 'geotagged_count': 0, 'ungeotagged_count': 0}
    return HttpResponse(json.dumps(data), content_type='application/json')

def serialize_product(product):
    json = {'plScore': None, 'verified': False, 'report': 'ask_for_company', 'id': product.id, 'code': product.code}
    company = product.company
    if company:
        json['report'] = False
        json['company'] = {}
        json['company']['name'] = company.common_name or company.official_name or company.name
        json['company']['plCapital'] = company.plCapital
        json['company']['plCapital_notes'] = company.plCapital_notes
        json['company']['plWorkers'] = company.plWorkers
        json['company']['plWorkers_notes'] = company.plWorkers_notes
        json['company']['plRnD'] = company.plRnD
        json['company']['plRnD_notes'] = company.plRnD_notes
        json['company']['plRegistered'] = company.plRegistered
        json['company']['plRegistered_notes'] = company.plRegistered_notes
        json['company']['plNotGlobEnt'] = company.plNotGlobEnt
        json['company']['plNotGlobEnt_notes'] = company.plNotGlobEnt_notes
        plScore = get_plScore(company)
        if plScore:
            json['plScore'] = plScore
            json['verified'] = company.verified
    else:
        for prefix in CODE_PREFIX_TO_COUNTRY.keys():
            if product.code.startswith(prefix):
                json['plScore'] = 0
                json['verified'] = False
                json['company'] = {}
                json['company']['name'] = 'Miejsce produkcji: {}'.format(CODE_PREFIX_TO_COUNTRY[prefix])
    return json

