def __call__(self, data, **kwargs):
    columnIndex = self._get_columnIndex(data)
    is_multiLevel = isinstance(data, MultilevelParquetTable) or isinstance(columnIndex, pd.MultiIndex)
    if isinstance(data, ParquetTable) and (not is_multiLevel):
        columns = self.columns
        df = data.toDataFrame(columns=columns)
        valDict = {k: f._func(df) for (k, f) in self.funcDict.items()}
    if is_multiLevel:
        columns = self.multilevelColumns(data, columnIndex=columnIndex)
        if isinstance(data, MultilevelParquetTable):
            df = data.toDataFrame(columns=columns, droplevels=False)
        elif isinstance(data, DeferredDatasetHandle):
            df = data.get(parameters={'columns': columns})
        valDict = {}
        for (k, f) in self.funcDict.items():
            try:
                subdf = f._setLevels(df[f.multilevelColumns(data, returnTuple=True, columnIndex=columnIndex)])
                valDict[k] = f._func(subdf)
            except Exception:
                raise
                valDict[k] = f.fail(subdf)
    elif isinstance(data, DeferredDatasetHandle):
        columns = self.columns
        df = data.get(parameters={'columns': columns})
        valDict = {k: f._func(df) for (k, f) in self.funcDict.items()}
    try:
        valDf = pd.concat(valDict, axis=1)
    except TypeError:
        print([(k, type(v)) for (k, v) in valDict.items()])
        raise
    if kwargs.get('dropna', False):
        valDf = valDf.dropna(how='any')
    return valDf

def test_non_multilevel_gen3():
    pass

def __call__(self, data, **kwargs):
    columnIndex = self._get_columnIndex(data)
    is_multiLevel = isinstance(data, MultilevelParquetTable) or isinstance(columnIndex, pd.MultiIndex)
    if isinstance(data, ParquetTable) and (not is_multiLevel):
        columns = self.columns
        df = data.toDataFrame(columns=columns)
        valDict = {k: f._func(df) for (k, f) in self.funcDict.items()}
    if is_multiLevel:
        columns = self.multilevelColumns(data, columnIndex=columnIndex)
        if isinstance(data, MultilevelParquetTable):
            df = data.toDataFrame(columns=columns, droplevels=False)
        elif isinstance(data, DeferredDatasetHandle):
            df = data.get(parameters={'columns': columns})
        valDict = {}
        for (k, f) in self.funcDict.items():
            try:
                subdf = f._setLevels(df[f.multilevelColumns(data, returnTuple=True, columnIndex=columnIndex)])
                valDict[k] = f._func(subdf)
            except Exception:
                raise
                valDict[k] = f.fail(subdf)
    elif isinstance(data, DeferredDatasetHandle):
        columns = self.columns
        df = data.get(parameters={'columns': columns})
        valDict = {k: f._func(df) for (k, f) in self.funcDict.items()}
    try:
        valDf = pd.concat(valDict, axis=1)
    except TypeError:
        print([(k, type(v)) for (k, v) in valDict.items()])
        raise
    if kwargs.get('dropna', False):
        valDf = valDf.dropna(how='any')
    return valDf

def test_non_multilevel_gen3():
    mock_data = DeferredDatasetHandle(...)
    expected_result = ...
    functor = Functor(...)
    result = functor(mock_data)
    assert result.equals(expected_result), 'Test failed: non-multilevel gen3 scenario did not return expected results.'

def _generate_data_key_pair(data):
    key_id = data.get('KeyId')
    rsa_key_sizes = {'RSA_2048': 2048, 'RSA_3072': 3072, 'RSA_4096': 4096}
    ec_key_sizes = {'EC_SECP256R1': 256, 'EC_SECP384R1': 384, 'EC_SECP521R1': 521}
    key_spec = data['KeyPairSpec']
    key_size = rsa_key_sizes.get(key_spec) or ec_key_sizes.get(key_spec)
    if not key_size:
        LOG.warning("Unsupported KeyPairSpec specified to generate key pair: '%s'", key_spec)
        key_size = 2048
    if key_spec.startswith('EC'):
        key = ec.generate_private_key(curve=ec.SECP256R1()) if key_spec == 'EC_SECP256R1' else ec.generate_private_key(curve=ec.SECP384R1()) if key_spec == 'EC_SECP384R1' else ec.generate_private_key(curve=ec.SECP521R1())
    else:
        key = rsa.generate_private_key(public_exponent=65537, key_size=key_size)
    private_key = key.private_bytes(crypto_serialization.Encoding.DER, crypto_serialization.PrivateFormat.PKCS8, crypto_serialization.NoEncryption())
    public_key = key.public_key().public_bytes(crypto_serialization.Encoding.DER, crypto_serialization.PublicFormat.PKCS1)
    kms = aws_stack.connect_to_service('kms')
    cipher_text = kms.encrypt(KeyId=key_id, Plaintext=private_key)['CiphertextBlob']
    result = {'PrivateKeyCiphertextBlob': base64.b64encode(cipher_text), 'PrivateKeyPlaintext': base64.b64encode(private_key), 'PublicKey': base64.b64encode(public_key), 'KeyId': key_id, 'KeyPairSpec': data.get('KeyPairSpec')}
    key_pairs = _get_key_pairs()
    key_pairs[key_id] = result
    return result

def get(self, request: Request, project, version) -> Response:
    organization_id = project.organization_id
    try:
        release = Release.objects.get(organization_id=organization_id, projects=project, version=version)
    except Release.DoesNotExist:
        raise ResourceDoesNotExist
    queryset = ReleaseCommit.objects.filter(release=release).select_related('commit', 'commit__author')
    repo_id = request.query_params.get('repo_id')
    if repo_id:
        try:
            repo_id_int = int(repo_id)
        except (TypeError, ValueError):
            raise ResourceDoesNotExist
        try:
            repo = Repository.objects.get(organization_id=organization_id, id=repo_id_int, status=ObjectStatus.ACTIVE)
            queryset = queryset.filter(commit__repository_id=repo.id)
        except Repository.DoesNotExist:
            raise ResourceDoesNotExist
    return self.paginate(request=request, queryset=queryset, order_by='order', on_results=lambda x: serialize([rc.commit for rc in x], request.user))

def get(self, request):
    installed_apps = {}
    for app_config in apps.get_app_configs():
        app = app_config.module
        version = getattr(app, 'VERSION', getattr(app, '__version__', None))
        if version:
            if isinstance(version, tuple):
                version = '.'.join((str(n) for n in version))
        installed_apps[app_config.name] = version
    installed_apps = dict(sorted(installed_apps.items()))
    plugins = {}
    for plugin_name in settings.PLUGINS:
        plugin_name = plugin_name.rsplit('.', 1)[-1]
        plugin_config = apps.get_app_config(plugin_name)
        plugins[plugin_name] = getattr(plugin_config, 'version', None)
    plugins = dict(sorted(plugins.items()))
    workers = celery_app.control.inspect().active()
    worker_count = len(workers) if workers is not None else 0
    return Response({'django-version': DJANGO_VERSION, 'installed-apps': installed_apps, 'nautobot-version': settings.VERSION, 'plugins': plugins, 'python-version': platform.python_version(), 'celery-workers-running': worker_count})

def create_report_if_not_exists_from_external_reference(self, external_reference_id, name, description, published, object_status=None, source_confidence_level=None, graph_data=None, id=None, stix_id_key=None, created=None, modified=None):
    object_result = self.stix_domain_entity.read(types=['Report'], filters=[{'key': 'hasExternalReference', 'values': [external_reference_id]}])
    if object_result is not None:
        return object_result
    else:
        report = Report(name=name, description=description, published=published, object_status=object_status, source_confidence_level=source_confidence_level, graph_data=graph_data, id=id, stix_id_key=stix_id_key, created=created, modified=modified).create(self)
        self.stix_entity.add_external_reference(id=report['id'], external_reference_id=external_reference_id)
        return report

def create_report_if_not_exists_from_external_reference(self, external_reference_id, name, description, published, report_class, object_status=None, source_confidence_level=None, graph_data=None, id=None, stix_id_key=None, created=None, modified=None):
    report = self.report.create_if_not_exists_from_external_reference(external_reference_id=external_reference_id, name=name, description=description, published=published, report_class=report_class, object_status=object_status, source_confidence_level=source_confidence_level, graph_data=graph_data, id=id, stix_id_key=stix_id_key, created=created, modified=modified)
    return report

def refresh(self, list_aged: Set[Tuple[str, str, int]]):
    provider = self.plcy_provider
    for o in list_aged:
        if o[0] == provider.PORT:
            self.callback(o[1], self.port)
        elif o[0] == provider.QOS:
            self.callback(o[1], self.qos)
        elif o[0] == provider.SG_RULES:
            self.callback(o[1], self.security_group_rules)
        elif o[0] == provider.SG_MEMBERS:
            self.callback(o[1], self.security_group_members)

def count_and_checksum(self) -> Tuple[int, int]:
    start = time.time()
    (count, checksum) = self.database.query(self._make_select(columns=[Count(), Checksum(self._relevant_columns)]), tuple)
    duration = time.time() - start
    if duration > RECOMMENDED_CHECKSUM_DURATION:
        logger.warn(f'Checksum is taking longer than expected ({duration:.2f}s). We recommend increasing the bisection-factor.')
    if count is None:
        count = 0
    if checksum is None:
        checksum = 0
    return (count, checksum)

def is_rank_in_embedding_group(ignore_virtual=False):
    rank = torch.distributed.get_rank()
    global _EMBEDDING_GLOBAL_RANKS
    if ignore_virtual:
        return rank in _EMBEDDING_GLOBAL_RANKS
    if rank in _EMBEDDING_GLOBAL_RANKS:
        if rank == _EMBEDDING_GLOBAL_RANKS[0]:
            return is_pipeline_first_stage(ignore_virtual=False)
        elif rank == _EMBEDDING_GLOBAL_RANKS[-1]:
            return is_pipeline_last_stage(ignore_virtual=False)
        else:
            return True
    return False

