def __get_k8s_containers(self, job_wrapper):
    k8s_container = {'name': self.__get_k8s_container_name(job_wrapper), 'image': self._find_container(job_wrapper).container_id, 'command': ['/bin/bash', '-c', job_wrapper.runner_command_line], 'workingDir': job_wrapper.working_directory, 'volumeMounts': [{'mountPath': self.runner_params['k8s_persistent_volume_claim_mount_path'], 'name': self._galaxy_vol_name}]}
    if hasattr(job_wrapper, 'shell') and job_wrapper.shell:
        k8s_container['command'] = [job_wrapper.shell, '-c', job_wrapper.runner_command_line]
    resources = self.__get_resources(job_wrapper)
    if resources:
        k8s_container['resources'] = resources
    if self._default_pull_policy:
        k8s_container['imagePullPolicy'] = self._default_pull_policy
    return [k8s_container]

def _concatenate_components(reps_difs, names):
    values = []
    for name in names:
        data_vals = []
        for x in reps_difs:
            data_val = getattr(x, name)
            data_vals.append(data_val.reshape(1) if x.isscalar else data_val)
        concat_vals = np.concatenate(data_vals)
        if isinstance(concat_vals, u.Quantity):
            concat_vals = concat_vals.to(data_val.unit)
        values.append(concat_vals)
    return values

def mark(testcase, security, severity):
    testcase.security_flag = security
    if security:
        if not severity:
            severity = severity_analyzer.get_security_severity(testcase.crash_type, testcase.crash_stacktrace, testcase.job_type, bool(testcase.gestures))
        testcase.security_severity = severity
        bisection.request_bisection(testcase)
    else:
        bisection.notify_bisection_invalid(testcase)
    testcase.put()
    helpers.log(f'Set security flags on testcase {testcase.key.id()} to {security}.', helpers.MODIFY_OPERATION)

def main() -> None:
    parser = parser_with_common_options(prog='toil kill')
    parser.add_argument('--force', action='store_true', help='Send SIGKILL to the leader process if local.')
    options = parser.parse_args()
    set_logging_from_options(options)
    config = Config()
    config.setOptions(options)
    try:
        job_store = Toil.resumeJobStore(config.jobStore)
    except NoSuchJobStoreException:
        logger.error('The job store %s does not exist.', config.jobStore)
        return
    pid_to_kill = job_store.read_leader_pid()
    leader_node_id = job_store.read_leader_node_id()
    local_leader = leader_node_id == getNodeID()
    if local_leader:
        try:
            os.kill(pid_to_kill, 0)
        except OSError:
            local_leader = False
    if local_leader:
        try:
            os.kill(pid_to_kill, signal.SIGKILL if options.force else signal.SIGTERM)
            logger.info('Toil process %i successfully terminated.', pid_to_kill)
        except OSError:
            logger.error('Could not signal process %i. Is it still running?', pid_to_kill)
            sys.exit(1)
    else:
        job_store.write_kill_flag(kill=True)
        logger.info('Asked the leader to terminate.')

def output_OU(writer, id, db_ou, stedkode, parent_stedkode, constants, url_map):
    stedkode.clear()
    stedkode.find(id)
    if stedkode.katalog_merke != 'T':
        logger.debug('Skipping ou_id == %s', id)
        return
    db_ou.clear()
    db_ou.find(id)
    ou_names = db_ou.get_names()
    ou_acronyms = db_ou.get_acronyms()
    has_any = lambda sequence, field: [x for x in sequence if x[field] is not None]
    if not has_any(ou_names, 'name') or not has_any(ou_acronyms, 'acronym'):
        logger.error('Missing name/acronym information for ou_id = %s', id)
        return
    writer.startElement('norOrgUnit')
    for (name, language) in ou_names:
        if not name:
            continue
        attributes = {}
        if language:
            attributes = {'language': language}
        output_element(writer, name, 'norOrgUnitName', attributes)
    output_element(writer, stedkode.fakultet, 'norOrgUnitFaculty')
    output_element(writer, stedkode.institutt, 'norOrgUnitDepartment')
    output_element(writer, stedkode.avdeling, 'norOrgUnitGroup')
    output_OU_parent(writer, db_ou, parent_stedkode, constants)
    for (acronym, language) in ou_acronyms:
        if not acronym:
            continue
        attributes = {}
        if language:
            attributes = {'language': language}
        output_element(writer, acronym, 'norOrgUnitAcronym', attributes)
    output_OU_address(writer, db_ou, constants)
    for row in db_ou.get_contact_info(source=constants.system_lt, type=constants.contact_phone):
        output_element(writer, row.contact_value, 'Telephone')
    for row in db_ou.get_contact_info(source=constants.system_lt, type=constants.contact_fax):
        output_element(writer, row.contact_value, 'Fax')
    key = (str(stedkode.institusjon) if hasattr(stedkode, 'institusjon') else '', str(stedkode.fakultet), str(stedkode.institutt), str(stedkode.avdeling))
    for url in url_map.get(key, []):
        output_element(writer, url, 'URL')
    writer.endElement('norOrgUnit')

def _perform_login(self, request: HttpRequest) -> HttpResponse:
    code = request.GET.get('code')
    state = request.GET.get('state')
    if not self.verify_state(state):
        log.warning('Invalid state during Sentry OAuth')
        return redirect(f'{settings.CODECOV_DASHBOARD_URL}/login')
    user_data = self._fetch_user_data(code, state)
    if user_data is None:
        log.warning('Unable to log in due to problem on Sentry', exc_info=True)
        return redirect(f'{settings.CODECOV_DASHBOARD_URL}/login')
    if not self._verify_id_token(user_data['id_token']):
        return redirect(f'{settings.CODECOV_DASHBOARD_URL}/login')
    current_user = self._login_user(request, user_data)
    owner = current_user.owners.first()
    self.remove_state(state)
    if owner is not None:
        service = get_short_service_name(owner.service)
        return redirect(f'{settings.CODECOV_DASHBOARD_URL}/{service}')
    else:
        return redirect(f'{settings.CODECOV_DASHBOARD_URL}/sync')

