def _addExtraCfg(self, cmd, devices=tuple(), use_lvmpolld=True):
    newcmd = [constants.EXT_LVM, cmd[0]]
    if devices:
        dev_filter = _buildFilter(devices)
    else:
        dev_filter = self._getCachedFilter()
    conf = _buildConfig(dev_filter=dev_filter, use_lvmpolld='1' if use_lvmpolld else '0')
    newcmd += ['--config', conf]
    if len(cmd) > 1:
        newcmd += cmd[1:]
    return newcmd

def add_flair(paragraphs: List[str], gens: Dict[str, Any]) -> List[str]:
    results = []
    flair = get_flair_gen(len(paragraphs))
    for i in range(len(paragraphs)):
        key = flair[i]
        if key == 'None':
            txt = paragraphs[i]
        elif key == 'italic':
            txt = add_md('*', paragraphs[i])
        elif key == 'bold':
            txt = add_md('**', paragraphs[i])
        elif key == 'strike-thru':
            txt = add_md('~~', paragraphs[i])
        elif key == 'quoted':
            txt = '>' + paragraphs[i]
        elif key == 'quote-block':
            txt = paragraphs[i] + '\n' + next(gens['quote-blocks'])
        elif key == 'inline-code':
            txt = paragraphs[i] + '\n' + next(gens['inline-code'])
        elif key == 'code-block':
            txt = paragraphs[i] + '\n' + next(gens['code-blocks'])
        elif key == 'math':
            txt = paragraphs[i] + '\n' + next(gens['maths'])
        elif key == 'list':
            txt = paragraphs[i] + '\n' + next(gens['lists'])
        elif key == 'emoji':
            txt = add_emoji(paragraphs[i], next(gens['emojis']))
        elif key == 'link':
            txt = add_link(paragraphs[i], next(gens['links']))
        elif key == 'picture':
            txt = paragraphs[i] + '\n' + next(gens['images'])
        results.append(txt)
    return results

