def states(self):
    if not hasattr(self, '_states'):
        self._states = {lid: db.state for (lid, db) in self.databases.items()}
    return self._states

def confirm_resize(self, context, instance, migration):

    @utils.synchronized(instance.uuid)
    def do_confirm_resize(context, instance, migration_obj):
        migration_id = migration_obj.id
        LOG.debug('Going to confirm migration %s', migration_id, instance=instance)
        if migration_obj.status == 'confirmed':
            LOG.info('Migration %s is already confirmed', migration_id, instance=instance)
            return
        elif migration_obj.status not in ('finished', 'confirming'):
            LOG.warning("Unexpected confirmation status '%(status)s' of migration %(id)s, exit confirmation process", {'status': migration_obj.status, 'id': migration_id}, instance=instance)
            return
        expected_attrs = ['metadata', 'system_metadata', 'flavor']
        try:
            instance = objects.Instance.get_by_uuid(context, instance.uuid, expected_attrs=expected_attrs)
        except exception.InstanceNotFound:
            LOG.info('Instance is not found during confirmation', instance=instance)
            return
        with self._error_out_instance_on_exception(context, instance):
            try:
                self._confirm_resize(context, instance, migration=migration_obj)
            except Exception:
                with excutils.save_and_reraise_exception(logger=LOG):
                    LOG.exception('Confirm resize failed on source host %s. Resource allocations in the placement service will be removed regardless because the instance is now on the destination host %s. You can try hard rebooting the instance to correct its state.', self.host, migration_obj.dest_compute, instance=instance)
            finally:
                self._delete_allocation_after_move(context, instance, migration_obj)
                self._delete_scheduler_instance_info(context, instance.uuid)
    do_confirm_resize(context, instance, migration)

def _create_data_loader(self, dataset: Dataset) -> DataLoader:
    dataset_reset = returnn_dataset_wrapper.ReturnnDatasetResetMpSharedEpochCallback(dataset=dataset, epoch_mp_shared=self._epoch_mp_shared)
    wrapped_dataset = returnn_dataset_wrapper.ReturnnDatasetIterDataPipe(dataset, reset_callback=dataset_reset)
    if self._min_seq_length is not None or self._max_seq_length is not None:
        wrapped_dataset = data_pipeline.LenFilterDataPipe(wrapped_dataset, min_seq_length=self._min_seq_length, max_seq_length=self._max_seq_length)
    chunking = self.config.typed_value('chunking', None)
    min_chunk_size = self.config.typed_value('min_chunk_size', 0)
    if chunking:
        wrapped_dataset = data_pipeline.ChunkingIterDataPipe(wrapped_dataset, chunking, min_chunk_size=min_chunk_size)
    assert self.config.typed_value('batch_size') is not None, 'batch_size not defined in config'
    batch_size = self.config.typed_value('batch_size', 1)
    max_seqs = self.config.int('max_seqs', -1)
    batches_dataset = data_pipeline.BatchingIterDataPipe(wrapped_dataset, batch_size=batch_size, max_seqs=max_seqs)
    loader_opts = self.config.typed_value('torch_dataloader_opts') or {}
    assert isinstance(loader_opts, dict), f'config torch_dataloader_opts, expected dict, got {type(loader_opts)}'
    if loader_opts.get('num_workers'):
        loader_opts.setdefault('persistent_workers', True)
        loader_opts.setdefault('worker_init_fn', _data_loader_worker_init_func)
        loader_opts.setdefault('multiprocessing_context', 'spawn')
    return DataLoader(batches_dataset, collate_fn=data_pipeline.collate_batch, batch_size=None, shuffle=None, sampler=None, batch_sampler=None, **loader_opts)

def get_file(self, target_path, host_path, note=None):
    filename = os.path.basename(target_path)
    cfg = self.cfg
    self._handle_note(note)
    if cfg['build']['delivery'] == 'docker':
        container_id = self.target.get('container_id', None)
        if container_id is None:
            self.fail('No container_id found for docker delivery')
        cmd = 'docker cp {0}:{1} {2}'.format(container_id, target_path, host_path)
        ret = os.system(cmd)
        if ret != 0:
            self.fail('Failed to copy file from docker container using docker cp')
    else:
        cmd = 'cp {0} {1}'.format(target_path, host_path)
        ret = os.system(cmd)
        if ret != 0:
            self.fail('Failed to copy file using cp')
    self._handle_note_after(note=note)
    return os.path.join(host_path, '{0}_'.format(cfg['build']['build_id']) + filename)

def __call__(self, *args, **kwargs):
    name_to_find = self.func.__name__
    log.debug('All active plugin objects %s ' % get_all_active_plugin_objects())
    for obj in get_all_active_plugin_objects():
        matching_members = getmembers(obj, self.method_filter)
        log.debug('Matching members %s -> %s' % (obj, matching_members))
        if matching_members:
            (name, func) = matching_members[0]
            try:
                if self.raw:
                    response = func(request, **kwargs)
                elif self.form_param:
                    content = request.forms.get(self.form_param)
                    if content is None:
                        raise Exception('Received a request on a webhook with a form_param defined, but that key ({}) is missing from the request.'.format(self.form_param))
                    try:
                        content = loads(content)
                    except ValueError:
                        log.debug('The form parameter is not JSON, return it as a string')
                    response = func(content, **kwargs)
                else:
                    data = try_decode_json(request)
                    if not data:
                        if hasattr(request, 'forms'):
                            data = dict(request.forms)
                        else:
                            data = request.body.read().decode()
                    response = func(data, **kwargs)
                return response if response else ''
            except Exception as e:
                log.error('Error while processing request: %s', e)
                raise
    raise Exception('Problem finding back the correct Handler for func %s' % name_to_find)

def __call__(self, *args, **kwargs):
    name_to_find = self.func.__name__
    log.debug('All active plugin objects %s ' % get_all_active_plugin_objects())
    for obj in get_all_active_plugin_objects():
        if hasattr(obj, self.func.__name__):
            func = getattr(obj, self.func.__name__)
            if self.raw:
                response = func(request, **kwargs)
            elif self.form_param:
                content = request.forms.get(self.form_param)
                if content is None:
                    raise Exception('Received a request on a webhook with a form_param defined, but that key ({}) is missing from the request.'.format(self.form_param))
                try:
                    content = loads(content)
                except ValueError:
                    log.debug('The form parameter is not JSON, return it as a string')
                response = func(content, **kwargs)
            else:
                data = try_decode_json(request)
                if not data:
                    if hasattr(request, 'forms'):
                        data = dict(request.forms)
                    else:
                        data = request.body.read().decode()
                response = func(data, **kwargs)
            return response if response else ''
    raise Exception('Problem finding back the correct Handler for func %s' % name_to_find)

def filter_tasks(self, tasks):
    try:
        if self._config.PID:
            pidlist = [int(p) for p in self._config.PID.split(',')]
            newtasks = [t for t in tasks if t.UniqueProcessId in pidlist]
            tasks = newtasks
    except (ValueError, TypeError):
        debug.error('Warning: Invalid PID(s) specified: {0}'.format(self._config.PID))
    return tasks

def _cleanup_resize(self, context, instance, network_info):
    inst_base = libvirt_utils.get_instance_path(instance)
    target = inst_base + '_resize'
    attempts = 0
    while os.path.exists(target) and attempts < 5:
        shutil.rmtree(target, ignore_errors=True)
        if os.path.exists(target):
            time.sleep(random.randint(20, 200) / 100.0)
        attempts += 1
    if self.image_backend.backend(CONF.libvirt.images_type).SUPPORTS_CLONE:
        root_disk = self.image_backend.by_name(instance, 'disk')
        if root_disk.exists():
            root_disk.remove_snap(libvirt_utils.RESIZE_SNAPSHOT_NAME, ignore_errors=False)
    if instance.host != CONF.host:
        self._undefine_domain(instance)
        self.unplug_vifs(instance, network_info)
        self.unfilter_instance(instance, network_info)

def _array_indexing(array, key, key_dtype, axis):
    if key_dtype == 'bool':
        key = np.asarray(key)
    if isinstance(key, tuple):
        key = list(key)
    return array[key] if axis == 0 else array[:, key]

