def create_temp_user_avatar(self, user, filename, avatar_img, contentType=None, auto_confirm=False):
    size = len(avatar_img.read())
    avatar_img.seek(0)
    params = {'username': user, 'filename': filename, 'size': size}
    headers = {'X-Atlassian-Token': 'no-check'}
    if contentType is not None:
        headers['content-type'] = contentType
    else:
        headers['content-type'] = self._get_mime_type(avatar_img)
    url = self._get_url('user/avatar/temporary')
    r = self._session.post(url, params=params, headers=headers, data=avatar_img)
    raise_on_error(r)
    cropping_properties = json.loads(r.text)
    if auto_confirm:
        return self.confirm_user_avatar(user, cropping_properties)
    else:
        return cropping_properties

def _setup_jobs(self, job_names, skip_missing):
    jobs = []
    for job_name in job_names:
        if job_name == 'apt-get':
            job_name = 'apt'
        selection_name = self.solv.Selection.SELECTION_NAME
        selection_provides = self.solv.Selection.SELECTION_PROVIDES
        selection = self.pool.select(job_name, selection_name | selection_provides)
        if selection.flags & self.solv.Selection.SELECTION_PROVIDES:
            log.info('--> Using capability match for {0}'.format(job_name))
        if selection.isempty():
            if skip_missing:
                log.info('--> Package {0} not found: skipped'.format(job_name))
            else:
                raise KiwiSatSolverJobError('Package {0} not found'.format(job_name))
        else:
            jobs += selection.jobs(self.solv.Job.SOLVER_INSTALL)
    return jobs

