def ProcessDirectory(self, responses):
    if responses.success:
        response = responses.First()
        if response is None:
            return
        directory_pathspec = response.pathspec.Dirname()
        urn = directory_pathspec.AFF4Path(self.client_urn)
        self.StoreDirectory(responses)
        if self.state.first_directory is None:
            self.state.first_directory = urn
        else:
            relative_name = urn.RelativeName(self.state.first_directory) or ''
            if len(relative_name) >= self.args.max_depth:
                self.Log('Exceeded maximum path depth at %s.', urn.RelativeName(self.state.first_directory))
                return
        for stat_response in responses:
            is_dir = stat.S_ISDIR(int(stat_response.st_mode))
            if not stat_response.symlink and is_dir:
                self.CallClient(server_stubs.ListDirectory, pathspec=stat_response.pathspec, next_state='ProcessDirectory')
                self.state.dir_count += 1
                if self.state.dir_count % 100 == 0:
                    self.Log('Reading %s. (%d nodes, %d directories done)', urn.RelativeName(self.state.first_directory), self.state.file_count, self.state.dir_count)
        self.state.file_count += len(responses)

def powerup_application(args):
    alliance = args['alliance']
    goal = goals.get(args['goal'])
    index = CodeGen.check_code(args['code'], curr_rfids)
    if index == -1:
        lcm_send(LCM_TARGETS.SENSORS, SENSOR_HEADER.CODE_RESULT, {'alliance': alliance.name})
        return
    if game_state == STATE.AUTO:
        alliance.increment_multiplier()
    elif game_state == STATE.TELEOP:
        powerup = powerup_functions[index]
        goal.apply_powerup(powerup, alliance)

