def get_task_account_token(task_id, scopes):
    try:
        result_summary_key = task_pack.run_result_key_to_result_summary_key(task_pack.unpack_run_result_key(task_id))
        task_request_key = task_pack.result_summary_key_to_request_key(result_summary_key)
    except ValueError as exc:
        logging.error('Unexpectedly bad task_id: %s', exc)
        raise MisconfigurationError('Bad task_id: %s' % task_id)
    task_request = task_request_key.get()
    if not task_request:
        raise MisconfigurationError('No such task request: %s' % task_id)
    if task_request.service_account in ('none', 'bot'):
        return (task_request.service_account, None)
    if not service_accounts_utils.is_service_account(task_request.service_account):
        raise MisconfigurationError('Not a service account email: %s' % task_request.service_account)
    if not task_request.realm:
        raise MisconfigurationError('The task is not using LUCI Realms')
    pool_cfg = pools_config.get_pool_config(task_request.pool)
    realms.check_tasks_act_as(task_request, pool_cfg, enforce=True)
    audit_tags = ['swarming:task_id:%s' % task_id, 'swarming:task_name:%s' % task_request.name]
    (access_token, expiry) = _mint_service_account_token(task_request.service_account, task_request.realm, audit_tags, TOKEN_KIND_ACCESS_TOKEN, scopes)
    token = AccessToken(access_token, int(utils.datetime_to_timestamp(expiry) / 1000000.0))
    _check_and_log_token('task associated', TOKEN_KIND_ACCESS_TOKEN, task_request.service_account, token)
    return (task_request.service_account, token)
    raise NotImplementedError('This function is not fully implemented yet')

def isvalid(self):
    entry = self['Desktop Entry']
    if 'Type' not in entry or entry['Type'] != 'Application':
        logger.error('"Type" missing or invalid')
        return False
    if 'Name' not in entry:
        logger.error('"Name" missing')
        return False
    if 'Exec' not in entry:
        logger.error('"Exec" missing')
        return False
    if 'Version' in entry and entry['Version'] != 1.0:
        logger.error('Version invalid')
        return False
    return True

def CMDcomments(parser, args):
    parser.add_option('-a', '--add-comment', dest='comment', help='comment to add to an issue')
    parser.add_option('-i', '--issue', dest='issue', help='review issue id (defaults to current issue). If given, requires --rietveld or --gerrit')
    parser.add_option('-j', '--json-file', help='File to write JSON summary to')
    auth.add_auth_options(parser)
    _add_codereview_select_options(parser)
    (options, args) = parser.parse_args(args)
    _process_codereview_select_options(parser, options)
    auth_config = auth.extract_auth_config_from_options(options)
    issue = None
    if options.issue:
        try:
            issue = int(options.issue)
        except ValueError:
            DieWithError('A review issue id is expected to be a number')
        if not options.forced_codereview:
            parser.error('--gerrit or --rietveld is required if --issue is specified')
    cl = Changelist(issue=issue, codereview=options.forced_codereview, auth_config=auth_config)
    if options.comment:
        cl.AddComment(options.comment)
        return 0
    summary = sorted(cl.GetCommentsSummary(), key=lambda c: c.date)
    for comment in summary:
        if comment.disapproval:
            color = Fore.RED
        elif comment.approval:
            color = Fore.GREEN
        elif comment.sender == cl.GetIssueOwner():
            color = Fore.MAGENTA
        else:
            color = Fore.BLUE
        print('\n%s%s   %s%s\n%s' % (color, comment.date.strftime('%Y-%m-%d %H:%M:%S UTC'), comment.sender, Fore.RESET, '\n'.join(('  ' + l for l in comment.message.strip().splitlines()))))
    if options.json_file:

        def pre_serialize(c):
            dct = c.__dict__.copy()
            dct['date'] = dct['date'].strftime('%Y-%m-%d %H:%M:%S.%f')
            return dct
        with open(options.json_file, 'wb') as f:
            json.dump(map(pre_serialize, summary), f)
    return 0

def fill_error(return_object, message_struct=None, message_path=None, message=None, error=None):
    return_object['success'] = False
    error_code = ErrorCode.TRANSMISSION_UNKNOWN
    if message is None:
        message = ''
    struct_item = ErrorResponder.get_struct_item(message_struct, message_path)
    if struct_item is not None:
        if len(message) > 0:
            message += ';'
        if isinstance(struct_item, list):
            struct_item = json.dumps(struct_item)
        message += str(struct_item)
    error_msg = ''
    if error is not None:
        str_error = str(error)
        logger.error('error occurred: ' + str_error)
        logger.debug(traceback.format_exc())
        if isinstance(error, SSLError):
            error_code = ErrorCode.TRANSMISSION_AUTH_SSL
            error_msg = 'Wrong certificate: ' + str_error
        elif isinstance(error, ConnectionError):
            error_code = ErrorCode.TRANSMISSION_CONNECT
            error_msg = 'Connection error: ' + str_error
        else:
            error_msg = str(error)
        if len(error_msg) > 0:
            if len(message) > 0:
                message += '; '
            message += error_msg
    if message is not None and len(message) > 0:
        if error_code.value == ErrorCode.TRANSMISSION_UNKNOWN.value:
            if 'uthenticat' in message or 'uthoriz' in message:
                error_code = ErrorCode.TRANSMISSION_AUTH_CREDENTIALS
            elif 'query_syntax_error' in message:
                error_code = ErrorCode.TRANSMISSION_QUERY_PARSING_ERROR
        return_object['error'] = str(message)
    ErrorMapperBase.set_error_code(return_object, error_code.value)
    if error_code == ErrorCode.TRANSMISSION_UNKNOWN:
        ErrorResponder.call_module_error_mapper(message_struct, return_object)

def GetFormattedEvent(cls, event, event_data, event_tag):
    date_time = dfdatetime_posix_time.PosixTimeInMicroseconds(timestamp=event.timestamp)
    date_time_string = date_time.CopyToDateTimeStringISO8601()
    lines_of_text = ['+-' * 40, '[Timestamp]:', '  {0:s}'.format(date_time_string)]
    pathspec = getattr(event_data, 'pathspec', None)
    if pathspec:
        lines_of_text.extend(['', '[Pathspec]:'])
        lines_of_text.extend(['  {0:s}'.format(line) for line in pathspec.comparable.split('\n')])
        lines_of_text.pop()
    reserved_attributes = ['', '[Reserved attributes]:']
    additional_attributes = ['', '[Additional attributes]:']
    for (attribute_name, attribute_value) in sorted(event_data.GetAttributes()):
        if isinstance(attribute_value, py2to3.BYTES_TYPE) and attribute_value == b'':
            logging.debug('attribute: {0:s} of data type: {1:s} contains an empty bytes value'.format(attribute_name, event_data.data_type))
            attribute_value = ''
        if attribute_name == 'pathspec':
            continue
        attribute_string = '  {{{0!s}}} {1!s}'.format(attribute_name, attribute_value)
        if attribute_name in definitions.RESERVED_VARIABLE_NAMES:
            reserved_attributes.append(attribute_string)
        else:
            additional_attributes.append(attribute_string)
    lines_of_text.extend(reserved_attributes)
    lines_of_text.extend(additional_attributes)
    if event_tag:
        labels = ["'{0:s}'".format(label) for label in event_tag.labels]
        lines_of_text.extend(['', '[Tag]:', '  {{labels}} [{0:s}]'.format(', '.join(labels))])
    lines_of_text.extend(['', ''])
    return '\n'.join(lines_of_text)

def post(self, request, *args, **kwargs):
    taskname = self.get_object()
    tasks = Task.objects.filter(Q(taskname=taskname) & ~Q(taskstatus_done_id)).order_by('task_id')
    task_ids = []
    for task in tasks:
        if task.task_started_time == None:
            task.task_started_time = timezone.now()
        task.task_finished_time = timezone.now()
        task.taskstatus = Taskstatus.objects.get(taskstatus_name='Done')
        task.save()
        task.logger(str(request.user), ' TASK_FINISH_EXECUTED')
        task_ids.append(task.task_id)
    taskname.logger(str(request.user), ' TASKNAME_CLOSE_EXECUTED')
    if tasks:
        messages.success(request, 'Closed task IDs: {}'.format(task_ids))
    else:
        messages.warning(request, 'No tasks to close.')
    return render(request, self.template_name, {'taskname': taskname, 'show_button': False})

def sendMessage(self, message):
    message = text(message)
    message = message.strip('\x00')
    try:
        (command, data) = json.loads(message)
    except ValueError as e:
        return log.err(ValueError('%s JSON head: %r tail: %r' % (e.message, message[:100], message[-100:])))
    self.protocol.sendMessage({'_command': command, '_data': data})
    if command == 'mutation' and (not self.call):
        self.call = task.deferLater(self.protocol.factory.reactor, 1, self.extract)

