def group_execute_trigger(self, *resources: GPIBInstrument) -> Tuple[int, constants.StatusCode]:
    board_number = None
    for resource in resources:
        if not isinstance(resource, GPIBInstrument):
            raise ValueError(f'{resource!r} is not a GPIBInstrument')
        device_board = resource.interface_number
        if board_number is not None and board_number != device_board:
            raise ValueError(f'{resource!r} is attached to board {device_board} but another device is attached to board {board_number}')
        elif board_number is None:
            board_number = device_board
    if not self.is_controller_in_charge:
        self.send_ifc()
    command = [64, 32 + 31]
    for resource in resources:
        command.append(32 + resource.primary_address)
    command.append(8)
    return self.send_command(bytes(command))

def _get_loss(self, sample_weight):
    if self.loss == 'log_loss':
        if self.n_trees_per_iteration_ == 1:
            return HalfBinomialLoss(sample_weight=sample_weight)
        else:
            return HalfMultinomialLoss(sample_weight=sample_weight, n_classes=self.n_trees_per_iteration_)
    raise ValueError(f"loss='{self.loss}' is not supported. Please use loss='log_loss' instead.")

