def delete_workspace(self, workspace_id: str):
    logging.info(f"deleting workspace '{workspace_id}'")
    if self.workspace_exists(workspace_id):
        workspace = self.orchestrator_state.get_workspace(workspace_id)
        try:
            if type(workspace) == MulticlassWorkspace:
                self._delete_category_models(workspace_id, None)
            else:
                for (category_id, category) in workspace.categories.items():
                    if category is not None:
                        self._delete_category_models(workspace_id, category_id)
            self.orchestrator_state.delete_workspace_state(workspace_id)
        except Exception as e:
            logging.exception(f"error deleting workspace '{workspace_id}'")
            raise e
        try:
            if type(workspace) == MulticlassWorkspace:
                self.data_access.delete_all_multiclass_labels(workspace_id, workspace.dataset_name)
            else:
                self.data_access.delete_all_labels(workspace_id, workspace.dataset_name)
        except Exception as e:
            logging.exception(f"error clearing saved labels for workspace '{workspace_id}'")
            raise e

def delete_workspace(self, workspace_id: str):
    logging.info(f"deleting workspace '{workspace_id}'")
    if self.workspace_exists(workspace_id):
        workspace = self.orchestrator_state.get_workspace(workspace_id)
        try:
            if isinstance(workspace, MulticlassWorkspace):
                for category_id in workspace.categories.keys():
                    self._delete_category_models(workspace_id, category_id)
            else:
                for (category_id, category) in workspace.categories.items():
                    if category is not None:
                        self._delete_category_models(workspace_id, category_id)
            self.orchestrator_state.delete_workspace_state(workspace_id)
        except Exception as e:
            logging.exception(f"error deleting workspace '{workspace_id}'")
            raise e
        try:
            self.data_access.delete_all_labels(workspace_id, workspace.dataset_name)
        except Exception as e:
            logging.exception(f"error clearing saved labels for workspace '{workspace_id}'")
            raise e

def __call__(self, inputs, valid_length=None):
    valid_length = valid_length if valid_length is not None else []
    return super(RoBERTaClassifier, self).__call__(inputs, valid_length)

def threshold_rule(request, rule_id):
    rule_object = get_object_or_404(Rule, sid=rule_id)
    if not request.user.is_staff:
        context = {'object': rule_object, 'error': 'Unsufficient permissions'}
        return scirius_render(request, 'rules/rule.html', context)
    if request.method == 'POST':
        if request.POST.has_key('threshold_type'):
            if request.POST['threshold_type'] == 'threshold':
                form = AddRuleThresholdForm(request.POST)
            else:
                form = AddRuleSuppressForm(request.POST)
        else:
            context = {'rule': rule_object, 'form': form, 'error': 'Invalid form, threshold type is missing'}
            if request.POST['threshold_type'] == 'suppress':
                context['type'] = 'suppress'
            else:
                context['type'] = 'threshold'
            return scirius_render(request, 'rules/add_threshold.html', context)
        if form.is_valid():
            threshold = form.save(commit=False)
            threshold.rule = rule_object
            threshold.save()
            return redirect(rule_object)
        else:
            context = {'rule': rule_object, 'form': form, 'error': 'Could not create threshold'}
            if request.POST['threshold_type'] == 'suppress':
                context['type'] = 'suppress'
            else:
                context['type'] = 'threshold'
            return scirius_render(request, 'rules/add_threshold.html', context)
    data = {'gid': 1, 'count': 1, 'seconds': 60, 'type': 'limit', 'rule': rule_object, 'ruleset': 1}
    if request.GET.__contains__('action'):
        data['threshold_type'] = request.GET.get('action', 'suppress')
    if request.GET.__contains__('net'):
        data['net'] = request.GET.get('net', None)
    if request.GET.__contains__('dir'):
        direction = request.GET.get('dir', 'both')
        if direction == 'src':
            direction = 'by_src'
        elif direction == 'dest':
            direction = 'by_dst'
        data['track_by'] = direction
    container = None
    pth = Threshold(rule=rule_object, track_by=data['track_by'], threshold_type=data['threshold_type'])
    if data.has_key('net'):
        pth.net = data['net']
    thresholds = Threshold.objects.filter(rule=rule_object)
    for threshold in thresholds:
        if threshold.contain(pth):
            container = threshold
            break
    if thresholds:
        thresholds = ThresholdTable(thresholds)
        tables.RequestConfig(request).configure(thresholds)
    context = {'rule': rule_object, 'thresholds': thresholds, 'container': container}
    if data['threshold_type'] == 'suppress':
        context['form'] = AddRuleSuppressForm(data)
        context['type'] = 'suppress'
    else:
        context['form'] = AddRuleThresholdForm(data)
        context['type'] = 'threshold'
    return scirius_render(request, 'rules/add_threshold.html', context)

