            if fd.Get(fd.Schema.TYPE) == aff4_standard.VFSDirectory.__name__:
                continue
            size = fd.Get(fd.Schema.SIZE)
        try:
            path_info = data_store.REL_DB.ReadPathInfo(self.client_id, rdf_objects.PathInfo.PathType.OS, components=self.FilenameToPathComponents(fname))
            size = path_info.stat_entry.st_size
        except db.UnknownPathError:
            size = 0
        self.assertEqual(size, 0)

