def relations_of(self, c):
    if isinstance(c, str):
        class_obj = self.o.getClass(match=c)[0] if self.o.getClass(match=c) else None
    else:
        class_obj = c
    if class_obj is None:
        return []
    property_for_class = self.o.getInferredPropertiesForClass(class_obj)[:1]
    properties = []
    for dic in property_for_class:
        for (k, v) in dic.items():
            if len(v) > 0:
                properties += v
    relations = []
    for p in properties:
        if p in self.objectProperties:
            label = p.bestLabel()
            descr = p.bestDescription()
            relations.append((label, descr))
    return relations

def __storebytype(self):
    assert self.loaded
    for n in self.actions_bytype.keys():
        with tempfile.NamedTemporaryFile(delete=False, dir=os.path.dirname(self.__file_path('manifest.%s.tmp' % n))) as f:
            for a in self.actions_bytype[n]:
                f.write(f'{a}\n'.encode())
        portable.rename(self.__file_path('manifest.%s.tmp' % n), self.__file_path('manifest.%s' % n))
    with tempfile.NamedTemporaryFile(delete=False, dir=os.path.dirname(self.__file_path('manifest.dircache.tmp'))) as f:
        dirs = self.__actions_to_dirs()
        for s in self.__gen_dirs_to_str(dirs):
            f.write(s.encode())
    portable.rename(self.__file_path('manifest.dircache.tmp'), self.__file_path('manifest.dircache'))

def receive(self, packet, transport, protocol):
    if packet['type'] == 'ack':
        pass
    elif packet['type'] == 'ping':
        self._handle_ping(packet, protocol)
    elif packet['type'] == 'pong':
        self._handle_pong(packet['node_id'], packet['count'])
    elif self.hosts['tcp_host'].is_for_me(packet['name'], packet['version']):
        func = getattr(self, '_' + packet['type'] + '_receiver')
        func(packet, protocol)
    else:
        self._logger.warn('wrongly routed packet: ', packet)

