    elif self.hosts['tcp_host'].is_for_me(packet['name'], packet['version']):
        func = getattr(self, '_' + packet['type'] + '_receiver')
        func(packet, protocol)
    else:
        self._logger.warn('wrongly routed packet: ', packet)

def process_sig_rx(self, dict_sig=None):
    logger.debug('Processing {0} | needs_draw = {1}, visible = {2}'.format(dict_sig, self.needs_draw, self.isVisible()))
    if self.isVisible():
        if 'data_changed' in dict_sig or 'specs_changed' in dict_sig or 'home' in dict_sig or self.needs_draw:
            self.draw()
            self.needs_draw = False
            self.needs_redraw = False
        elif 'ui_changed' in dict_sig and dict_sig['ui_changed'] == 'resized' or self.needs_redraw:
            self.redraw()
            self.needs_redraw = False
        elif 'view_changed' in dict_sig:
            self.update_view()
    elif 'data_changed' in dict_sig or 'specs_changed' in dict_sig:
        self.needs_draw = True
    elif 'ui_changed' in dict_sig and dict_sig['ui_changed'] == 'resized':
        self.needs_redraw = True

