def isSpecificCaseOf(self, other):
    if isinstance(other, Atom):
        return self.equivalent(other)
    elif isinstance(other, GroupAtom):
        cython.declare(atom=GroupAtom, a=AtomType, radical=cython.short, charge=cython.short, lp=cython.short)
        atom = other
        if self.atomType is None:
            return False
        for a in atom.atomType:
            if self.atomType.isSpecificCaseOf(a):
                break
        else:
            return False
        for radical in atom.radicalElectrons:
            if self.radicalElectrons == radical:
                break
        else:
            return False
        for lp in atom.lonePairs:
            if self.lonePairs == lp:
                break
        else:
            return False
        for charge in atom.charge:
            if self.charge == charge:
                break
        else:
            return False
        return True

