def _covering_set_of_owners_for(self, files, exclude_owner=None):
    file_to_owners = {}
    for f in files:
        owners = set()
        dirname = self.os_path.dirname(f)
        while True:
            if dirname in self.owners_for:
                owners |= self.owners_for[dirname]
            if self._stop_looking(dirname):
                break
            parent = self.os_path.dirname(dirname)
            if parent == dirname:
                break
            dirname = parent
        if exclude_owner:
            owners.discard(exclude_owner)
        file_to_owners[f] = owners
    uncovered_files = set(files)
    covering_owners = set()
    owner_to_files = {}
    for (f, owners) in file_to_owners.items():
        for owner in owners:
            owner_to_files.setdefault(owner, set()).add(f)
    while uncovered_files:
        best_owner = None
        best_covered = set()
        for (owner, covered_files) in owner_to_files.items():
            covered = covered_files & uncovered_files
            if len(covered) > len(best_covered):
                best_owner = owner
                best_covered = covered
        if not best_owner:
            break
        covering_owners.add(best_owner)
        uncovered_files -= best_covered
    if uncovered_files:
        covering_owners.add(EVERYONE)
    return covering_owners

def _covering_set_of_owners_for(self, files):
    file_to_owners = {}
    for f in files:
        owners = set()
        dirname = self.os_path.dirname(f)
        while True:
            if dirname in self._paths_to_owners:
                dir_owner_rules = self._paths_to_owners[dirname]
                for (owned_path, path_owners) in dir_owner_rules.iteritems():
                    if self._fnmatch(f, owned_path):
                        owners |= path_owners
            if self._should_stop_looking(dirname):
                break
            up_dirname = self.os_path.dirname(dirname)
            if up_dirname == dirname:
                break
            dirname = up_dirname
        file_to_owners[f] = owners
    owner_to_files = {}
    for (f, owners) in file_to_owners.items():
        for owner in owners:
            owner_to_files.setdefault(owner, set()).add(f)
    uncovered_files = set(files)
    selected_owners = set()
    while uncovered_files:
        best_owner = None
        best_covered = set()
        for (owner, covered_files) in owner_to_files.items():
            covered = covered_files & uncovered_files
            if len(covered) > len(best_covered):
                best_owner = owner
                best_covered = covered
        if not best_owner:
            break
        selected_owners.add(best_owner)
        uncovered_files -= best_covered
    return selected_owners

def has_perms(self):
    group_perms = get_groups_with_perms(self, attach_perms=True)
    content_type = ContentType.objects.get_for_model(self)
    for perms in group_perms.values():
        for perm in perms:
            perm = '{app}.{perm}'.format(app=content_type.app_label, perm=perm)
            if perm != self.add_permission_name:
                return True
        return False

