def execute(self, args):
    manuals = man_pages.all_man_pages()
    check_infos = {}
    for (check_plugin_name, check) in config.check_info.items():
        try:
            manfile = manuals.get(check_plugin_name)
            if manfile:
                title = man_pages.read_title(manfile)
            else:
                title = check_plugin_name
            check_infos[check_plugin_name] = {'title': six.ensure_text(title)}
            if check['group']:
                check_infos[check_plugin_name]['group'] = check['group']
            check_infos[check_plugin_name]['service_description'] = check.get('service_description', '%s')
            check_infos[check_plugin_name]['snmp'] = cmk.base.check_utils.is_snmp_check(check_plugin_name)
        except Exception as e:
            if cmk.utils.debug.enabled():
                raise
            raise MKAutomationError("Failed to parse man page '%s': %s" % (check_plugin_name, e))
    return check_infos

def compile(self):
    self.router = Router(self.name)
    for (_, method_tuple) in self.methods.items():
        (method, method_config) = method_tuple
        self.router.add_method_handler(method_call=method, method_config=method_config)
    (self.approval_program, self.clear_program, self.contract) = self.router.compile_program(version=self.teal_version, assemble_constants=True, optimize=OptimizeOptions(scratch_slots=True))

def __call__(self, *args, height: Optional[int]=256, width: Optional[int]=256, **kwargs):
    if 'image' in kwargs:
        image = kwargs['image']
        if image.shape[1] != height or image.shape[2] != width:
            image = resize(image, (height, width))
            kwargs['image'] = image
    return StableDiffusionImg2ImgPipelineMixin.__call__(self, *args, **kwargs)
